import { PitchParams, Company, SearchParams, Pitch, SearchResult } from "../types";

export const generatePitch = async (params: PitchParams): Promise<Pitch[]> => {
  try {
    const response = await fetch('/api/pitch', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(params),
    });

    const contentType = response.headers.get("content-type");
    if (contentType && contentType.includes("application/json")) {
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || `Pitch Generation Failed: ${response.statusText}`);
      }
      return data.pitches || [];
    } else {
       const text = await response.text();
       console.error("Pitch API Error (Non-JSON):", text);
       throw new Error(`Server Error (${response.status}). Check console for details.`);
    }

  } catch (error) {
    console.error("Recon Pitch Error:", error);
    throw error;
  }
};

export const findLeads = async (params: SearchParams, signal?: AbortSignal): Promise<SearchResult> => {
  try {
    const response = await fetch('/api/leads', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(params),
      signal // Pass the abort signal to the fetch request
    });

    const contentType = response.headers.get("content-type");
    if (contentType && contentType.includes("application/json")) {
        const data = await response.json();
        if (!response.ok) {
            throw new Error(data.error || `Discovery Failed: ${response.statusText}`);
        }
        return {
            leads: data.leads || [],
            sources: data.sources || []
        };
    } else {
        const text = await response.text();
        console.error("Leads API Error (Non-JSON):", text);

        let msg = `Server Error (${response.status})`;
        if (response.status === 404) msg = "API Endpoint Not Found (404).";
        else if (response.status === 500) msg = "Internal Server Error (500).";

        throw new Error(msg);
    }

  } catch (error: any) {
    if (error.name === 'AbortError') {
      // Ignore abort errors, they are intentional
      throw error; 
    }
    console.error("Recon Discovery Error:", error);
    throw error;
  }
};

import { GoogleGenAI, Type } from "@google/genai";

interface Env {
  API_KEY: string;
}

export const onRequestPost = async (context: any) => {
  try {
    if (typeof process === 'undefined') {
      (globalThis as any).process = { env: {} };
    }

    const { request, env } = context;
    const apiKey = env.API_KEY || (typeof process !== 'undefined' ? process.env.API_KEY : null);

    if (!apiKey) {
      return new Response(JSON.stringify({ error: "Server Configuration Error: API Key missing." }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
      });
    }

    const { mode, industry, city, companyName, excludeNames, role } = await request.json();

    if (mode === 'lookup') {
        if (!companyName) return new Response(JSON.stringify({ error: "Company Name is required for lookup" }), { status: 400 });
    } else if (mode === 'discovery') {
        if (!industry || !city) return new Response(JSON.stringify({ error: "Industry and City are required" }), { status: 400 });
    } else if (mode === 'jobs') {
        if (!role || !city) return new Response(JSON.stringify({ error: "Role and City are required" }), { status: 400 });
    }

    const ai = new GoogleGenAI({ apiKey: apiKey });
    const model = 'gemini-3-flash-preview';

    const exclusionList = excludeNames && excludeNames.length > 0 ? excludeNames.join(', ') : "None";
    const today = new Date().toDateString();

    const systemInstruction = `
      You are an expert Lead Generation & Recruitment Intelligence AI.
      CURRENT DATE: ${today}.

      CORE DIRECTIVE: Prioritize finding CONTACT INFORMATION, OPEN ROLES, and FRESH INTELLIGENCE.

      SEARCH RULES:
      1. Use the googleSearch tool to find the company website, careers page, linkedin, and contact pages.
      2. FOR 'recentWork' AND 'signals': You MUST use Google Search to find data from the last 6 months.
      3. IF MODE IS 'jobs': Look specifically for open job listings matching the user's requested role.
      4. TIME CHECK: Compare found dates with CURRENT DATE (${today}).
      5. Ensure all URLs are full and valid (https://).
    `;

    let prompt = '';
    if (mode === 'lookup') {
        prompt = `Target: "${companyName}" in "${city || 'any location'}". Find verified contact details and checking for any open roles related to creative, tech, or marketing.
        CRITICAL: Search for the absolute latest news relative to ${today}.`;
    } else if (mode === 'jobs') {
        prompt = `Find 5 ACTIVE companies in ${city} that are currently hiring for "${role}".
        Exclude: ${exclusionList}.
        For each company, list specific open roles matching "${role}" or similar (include title and estimated salary if found).
        Also find their general contact info and hiring culture.`;
    } else {
        prompt = `Find 5 ACTIVE ${industry} companies in ${city}. Exclude: ${exclusionList}. 
        For every lead, find specific contact info. 
        CRITICAL: Search for their latest activities relative to ${today}.`;
    }

    // Strict Schema Definition
    const schema = {
      type: Type.OBJECT,
      properties: {
        leads: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              website: { type: Type.STRING },
              location: { type: Type.STRING },
              description: { type: Type.STRING },
              needs: { 
                type: Type.ARRAY, 
                items: { type: Type.STRING } 
              },
              heroProduct: { type: Type.STRING },
              phone: { type: Type.STRING },
              email: { type: Type.STRING },
              socials: { type: Type.STRING, description: "Space separated full URLs" },
              hotScore: { type: Type.INTEGER },
              hiringCulture: { type: Type.STRING, description: "Brief notes on their culture or hiring process" },
              openRoles: {
                type: Type.ARRAY,
                items: {
                   type: Type.OBJECT,
                   properties: {
                      title: { type: Type.STRING },
                      location: { type: Type.STRING },
                      type: { type: Type.STRING },
                      salary: { type: Type.STRING },
                      link: { type: Type.STRING }
                   }
                }
              },
              signals: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    type: { type: Type.STRING },
                    text: { type: Type.STRING, description: "Must be a recent event or fact found via search." },
                    confidence: { type: Type.STRING, enum: ["High", "Medium", "Low"] }
                  },
                  required: ["type", "text", "confidence"]
                }
              }
            },
            required: ["name", "website", "description", "hotScore", "email"]
          }
        }
      },
      required: ["leads"]
    };

    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        temperature: 0.4,
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: schema
      },
    });

    // With responseSchema, response.text is guaranteed to be valid JSON structure
    let data;
    try {
        data = JSON.parse(response.text || "{}");
    } catch (e) {
        // Fallback for extremely rare edge cases
        console.error("JSON Parse Error:", response.text);
        throw new Error("Invalid JSON response from AI");
    }

    const leads = (data.leads || []).map((lead: any, index: number) => ({
        ...lead,
        id: `gen-${Date.now()}-${index}`,
        status: 'New',
        recentWork: lead.description, 
        website: lead.website || "N/A",
        phone: lead.phone || "N/A",
        email: lead.email || "N/A",
        socials: lead.socials || "N/A",
        signals: lead.signals || [],
        location: lead.location || city,
        openRoles: (lead.openRoles || []).map((r: any, ri: number) => ({
            ...r,
            id: `role-${Date.now()}-${index}-${ri}`,
            status: 'Saved' // Default status for UI consistency if used
        }))
    }));

    // Extract Grounding Chunks (Sources)
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
    const sources = groundingChunks
        .map((chunk: any) => ({
            title: chunk.web?.title || "Web Source",
            uri: chunk.web?.uri
        }))
        .filter((s: any) => s.uri)
        .filter((v: any, i: number, a: any[]) => a.findIndex((t: any) => (t.uri === v.uri)) === i);

    return new Response(JSON.stringify({ leads, sources }), {
      status: 200,
      headers: { "Content-Type": "application/json" }
    });

  } catch (error: any) {
    console.error("Leads API Critical Error:", error);
    return new Response(JSON.stringify({ error: error.message || "Unknown Server Error" }), { 
        status: 500,
        headers: { "Content-Type": "application/json" }
    });
  }
};

import { GoogleGenAI, Type } from "@google/genai";

interface Env {
  API_KEY: string;
}

export const onRequestPost = async (context: any) => {
  try {
    if (typeof process === 'undefined') {
      (globalThis as any).process = { env: {} };
    }

    const { request, env } = context;
    const apiKey = env.API_KEY || (typeof process !== 'undefined' ? process.env.API_KEY : null);

    if (!apiKey) {
      return new Response(JSON.stringify({ error: "API Key not configured" }), {
        status: 500,
        headers: { "Content-Type": "application/json" },
      });
    }

    const { 
      companyName, 
      industry, 
      userSkills, 
      tone, 
      companySignals, 
      format = 'email', 
      context: pitchContext = 'sales',
      jobTitle 
    } = await request.json();

    const ai = new GoogleGenAI({ apiKey: apiKey });
    const model = 'gemini-3-flash-preview';

    let contextStr = "";
    if (companySignals && companySignals.length > 0) {
        contextStr = `COMPANY FACTS:\n${companySignals.join('\n')}\n`;
    }

    if (jobTitle) {
        contextStr += `\nTARGET ROLE: ${jobTitle}\n`;
    }

    let specificInstructions = "";

    // JOB APPLICATION MODE
    if (pitchContext === 'job_application') {
       if (format === 'linkedin_connect') {
        specificInstructions = `
        CONTEXT: Applying for ${jobTitle || 'a job'}.
        FORMAT: LinkedIn Connection Request to Hiring Manager.
        LENGTH: STRICTLY UNDER 300 CHARACTERS.
        SUBJECT LINE: Return an empty string "".
        STYLE: Professional, expressing interest, mention skills.
        `;
      } else {
        specificInstructions = `
        CONTEXT: Job Application for ${jobTitle || 'a role'}.
        FORMAT: Cover Email / Cold Email to Hiring Manager.
        LENGTH: Under 150 words.
        SUBJECT LINE: Required. Professional (e.g., Application for ${jobTitle} - [Name]).
        STYLE: Confident, matching skills to company needs.
        `;
      }
    } 
    // SALES MODE
    else {
      if (format === 'linkedin_connect') {
        specificInstructions = `
        FORMAT: LinkedIn Connection Request
        LENGTH: STRICTLY UNDER 300 CHARACTERS.
        SUBJECT LINE: Return an empty string "".
        STYLE: Casual, direct, mention the specific company fact.
        `;
      } else if (format === 'linkedin_inmail') {
        specificInstructions = `
        FORMAT: LinkedIn InMail
        LENGTH: Under 150 words.
        SUBJECT LINE: Required. Professional and catchy.
        STYLE: Conversational B2B.
        `;
      } else {
        specificInstructions = `
        FORMAT: Cold Email
        LENGTH: Under 100 words.
        SUBJECT LINE: Required. Intriguing.
        STYLE: ${tone}
        `;
      }
    }

    const prompt = `
      Target: ${companyName} (${industry})
      My Skills/Offer: ${userSkills}
      ${contextStr}
      ${specificInstructions}

      Generate 3 variations:
      1. Direct & Professional
      2. Value/Skill Focused
      3. Culture/Research Focused (Reference a fact)
    `;

    const systemInstruction = `
      You are an elite business communicator.
      1. Reference provided company facts.
      2. No hashtags.
      3. No buzzwords like "delve", "tapestry", "unlock".
      4. If format is 'linkedin_connect', the body MUST be < 300 chars.
    `;

    const response = await ai.models.generateContent({
      model: model,
      contents: { parts: [{ text: prompt }] },
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            pitches: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  angle: { type: Type.STRING },
                  subject: { type: Type.STRING },
                  body: { type: Type.STRING },
                },
                required: ["angle", "subject", "body"],
              },
            },
          },
          required: ["pitches"],
        },
        temperature: 0.7,
      },
    });

    const data = JSON.parse(response.text || "{}");

    return new Response(JSON.stringify(data), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });

  } catch (error: any) {
    console.error("Backend Pitch Error:", error);
    return new Response(JSON.stringify({ error: error.message }), {
      status: 500,
      headers: { "Content-Type": "application/json" },
    });
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Search, MapPin, Briefcase, ChevronRight, Globe, Loader2, Radar, Building2, Flame, ExternalLink, RefreshCw, UserSearch } from 'lucide-react';
import { Company, SearchMode, Source } from '../types';

interface SearchPaneProps {
  companies: Company[];
  sources?: Source[];
  selectedCompanyId: string | null;
  onSelectCompany: (id: string) => void;
  onSearch?: (mode: SearchMode, p1: string, p2: string) => void;
  onLoadMore?: () => void;
  isSearching?: boolean;
}

export const SearchPane: React.FC<SearchPaneProps> = ({ 
  companies,
  sources = [],
  selectedCompanyId, 
  onSelectCompany,
  onSearch,
  onLoadMore,
  isSearching = false
}) => {
  const [mode, setMode] = useState<SearchMode>('discovery');

  // Discovery Inputs
  const [industry, setIndustry] = useState('');
  const [city, setCity] = useState('');

  // Lookup Inputs
  const [companyName, setCompanyName] = useState('');
  const [lookupCity, setLookupCity] = useState('');

  // Jobs Inputs
  const [role, setRole] = useState('');
  const [jobCity, setJobCity] = useState('');

  // Loading Message State
  const [loadingText, setLoadingText] = useState('Searching...');

  // Infinite Scroll Ref
  const loadMoreRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isSearching) return;

    const messages = mode === 'jobs' ? [
        "Scanning Job Boards...",
        "Identifying Companies...",
        "Checking Career Pages...",
        "Evaluating Hiring Culture...",
        "Compiling Open Roles..."
    ] : [
        "Analyzing Industry...",
        "Finding Companies...",
        "Finding Contact Info...",
        "Verifying Details...",
        "Preparing Report..."
    ];

    let i = 0;
    const interval = setInterval(() => {
        setLoadingText(messages[i]);
        i = (i + 1) % messages.length;
    }, 1200);

    return () => clearInterval(interval);
  }, [isSearching, mode]);

  // Infinite Scroll Observer
  useEffect(() => {
    if (!onLoadMore || mode === 'lookup' || isSearching || companies.length === 0) return;

    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) {
        onLoadMore();
      }
    }, { threshold: 0.1 });

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => observer.disconnect();
  }, [companies.length, isSearching, mode, onLoadMore]);

  const handleSubmit = () => {
    if (!onSearch) return;

    if (mode === 'discovery') {
       if (industry && city) onSearch('discovery', industry, city);
    } else if (mode === 'jobs') {
       if (role && jobCity) onSearch('jobs', role, jobCity);
    } else {
       if (companyName) onSearch('lookup', companyName, lookupCity || 'Anywhere'); 
    }
  };

  const getHotScoreColor = (score: number) => {
    if (score >= 80) return 'from-red-500 to-orange-500';
    if (score >= 60) return 'from-orange-400 to-amber-400';
    return 'from-neutral-400 to-neutral-500';
  };

  return (
    <div className="flex flex-col h-full">

      {/* Search Header Area - Fixed Top */}
      <div className="mb-2 space-y-4 relative z-10 bg-neutral-50 dark:bg-neutral-950 pb-2">
        <div className="flex items-center justify-between px-1">
             <h2 className="text-lg font-semibold text-neutral-900 dark:text-white tracking-tight">
               Search
             </h2>
             {/* Mode Toggles */}
             <div className="flex p-1 rounded-lg bg-neutral-200 dark:bg-white/5 border border-neutral-200 dark:border-white/5">
                 <button
                    onClick={() => setMode('discovery')}
                    className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all ${mode === 'discovery' ? 'bg-white dark:bg-neutral-800 text-accent shadow-sm' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                 >
                    Leads
                 </button>
                 <button
                    onClick={() => setMode('jobs')}
                    className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all ${mode === 'jobs' ? 'bg-white dark:bg-neutral-800 text-accent shadow-sm' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                 >
                    Jobs
                 </button>
                 <button
                    onClick={() => setMode('lookup')}
                    className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all ${mode === 'lookup' ? 'bg-white dark:bg-neutral-800 text-accent shadow-sm' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                 >
                    Lookup
                 </button>
             </div>
        </div>

        <div className="space-y-3">
          {mode === 'discovery' && (
              <>
