          <button 
            onClick={handleSubmit}
            disabled={
                isSearching || 
                (mode === 'discovery' ? (!industry || !city) : 
                 mode === 'jobs' ? (!role || !jobCity) : 
                 !companyName)
            }
            className={`
              w-full flex items-center justify-center py-3 px-4 rounded-xl font-medium transition-all duration-300 shadow-lg 
              ${isSearching || (mode === 'discovery' ? (!industry || !city) : mode === 'jobs' ? (!role || !jobCity) : !companyName)
                ? 'bg-neutral-200 dark:bg-neutral-800 text-neutral-400 cursor-not-allowed shadow-none' 
                : 'bg-accent hover:bg-accent-glow text-white shadow-accent/20 hover:shadow-accent/40 active:scale-[0.98]'}
            `}
          >
            {isSearching && companies.length === 0 ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Search className="w-4 h-4 mr-2" />}
            {isSearching && companies.length === 0 ? (
                <span className="font-mono text-xs uppercase tracking-wide animate-pulse">{loadingText}</span>
            ) : (
                mode === 'discovery' ? 'Find Leads' : mode === 'jobs' ? 'Find Jobs' : 'Lookup'
            )}
          </button>
        </div>
      </div>

      {/* Soft Gradient Divider */}
      <div className="h-6 w-full bg-gradient-to-b from-neutral-50 via-neutral-50 to-transparent dark:from-neutral-950 dark:via-neutral-950 z-10 shrink-0"></div>

      {/* Results List - SCROLLABLE AREA */}
      <div id="results-container" className="flex-1 overflow-y-auto -mx-2 px-2 pb-4 space-y-3 min-h-0 custom-scrollbar">
        {companies.length === 0 && !isSearching && (
          <div className="h-full flex flex-col items-center justify-center text-center opacity-60 animate-fade-in p-8">
             <div className="w-16 h-16 rounded-full bg-neutral-100 dark:bg-neutral-900/50 flex items-center justify-center mb-4 ring-1 ring-neutral-200 dark:ring-white/5">
                 <Radar className="w-8 h-8 text-neutral-400" />
             </div>
             <h3 className="text-sm font-semibold text-neutral-900 dark:text-white mb-1">
               Ready to Search
             </h3>
             <p className="text-xs text-neutral-500 max-w-[200px] leading-relaxed">
                Enter your search criteria above to begin.
             </p>
          </div>
        )}

        {companies.map((company, index) => {
          const isSelected = selectedCompanyId === company.id;
          const animationDelay = `${(index % 10) * 50}ms`;
          const hotColor = getHotScoreColor(company.hotScore);
          const openRolesCount = company.openRoles?.length || 0;

          return (
            <div
              key={company.id}
              onClick={() => onSelectCompany(company.id)}
              style={{ animationDelay }}
              className={`
                relative p-4 rounded-xl border cursor-pointer transition-all duration-300 group opacity-0 animate-fade-in-up
                ${isSelected 
                  ? 'bg-white dark:bg-neutral-800 border-accent shadow-md ring-1 ring-accent z-10 scale-[1.01]' 
                  : 'bg-white dark:bg-neutral-900/50 border-neutral-200 dark:border-white/5 hover:border-neutral-300 dark:hover:border-white/20 hover:shadow-sm hover:bg-white dark:hover:bg-neutral-800/80'}
              `}
            >
              <div className="flex justify-between items-start">
                <div className="flex-1 mr-2">
                  <h3 className={`font-semibold text-sm transition-colors ${isSelected ? 'text-neutral-900 dark:text-white' : 'text-neutral-700 dark:text-neutral-200 group-hover:text-neutral-900 dark:group-hover:text-white'}`}>
                    {company.name}
                  </h3>
                  <div className="flex items-center mt-1 space-x-2">
                      {company.website !== 'N/A' && (
                        <>
                          <Globe className="w-3 h-3 text-neutral-400 group-hover:text-accent transition-colors" />
                          <a 
                             href={company.website.startsWith('http') ? company.website : `https://${company.website}`} 
                             target="_blank" 
                             rel="noreferrer"
                             onClick={(e) => e.stopPropagation()} 
                             className="text-xs text-neutral-500 hover:text-accent hover:underline truncate max-w-[150px] transition-colors"
                          >
                            {company.website.replace(/^https?:\/\/(www\.)?/, '')}
                          </a>
                        </>
                      )}
                  </div>
                  {openRolesCount > 0 && (
                      <div className="mt-2 inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-blue-500/10 text-blue-500 text-[10px] font-bold uppercase">
                          <UserSearch className="w-3 h-3" />
                          {openRolesCount} Open Role{openRolesCount !== 1 && 's'}
                      </div>
                  )}
                </div>

                {/* Hot Score Badge */}
                <div className={`
                    flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold text-white shadow-sm
                    bg-gradient-to-r ${hotColor}
                `}>
                    <Flame className="w-3 h-3 fill-white/90" />
                    <span>{company.hotScore}%</span>
                </div>
              </div>

              {/* Active Indicator Slide-in */}
              <div className={`
                  mt-3 flex items-center text-xs font-medium text-accent overflow-hidden transition-all duration-300 ease-out
                  ${isSelected ? 'max-h-6 opacity-100 translate-y-0' : 'max-h-0 opacity-0 -translate-y-2'}
              `}>
                  <span>Selected</span>
                  <ChevronRight className="w-3 h-3 ml-1" />
              </div>
            </div>
          );
        })}

        {/* Infinite Scroll Trigger Area */}
        {companies.length > 0 && (mode === 'discovery' || mode === 'jobs') && (
           <div ref={loadMoreRef} className="py-4 flex flex-col items-center justify-center opacity-70">
              {isSearching ? (
                 <div className="flex items-center gap-2 text-xs text-neutral-500">
                    <Loader2 className="w-4 h-4 animate-spin text-accent" />
                    <span className="animate-pulse">Loading more results...</span>
                 </div>
              ) : (
                 <div className="h-4"></div> // Spacer trigger
              )}
           </div>
        )}

        {/* Verified Sources Footer */}
        {sources.length > 0 && (
          <div className="mt-6 pt-4 border-t border-neutral-200 dark:border-white/10 opacity-70 hover:opacity-100 transition-opacity">
            <h4 className="text-[10px] font-bold uppercase text-neutral-500 mb-2">Verified Sources</h4>
            <div className="flex flex-wrap gap-2">
              {sources.map((source, idx) => (
                <a 
                  key={idx}
                  href={source.uri}
                  target="_blank"
                  rel="noreferrer"
                  className="flex items-center gap-1 px-2 py-1 rounded bg-neutral-100 dark:bg-white/5 border border-neutral-200 dark:border-white/10 text-[10px] text-neutral-600 dark:text-neutral-400 hover:text-accent hover:border-accent/30 transition-colors truncate max-w-full"
                  title={source.title}
                >
                  <ExternalLink className="w-3 h-3" />
                  <span className="truncate max-w-[150px]">{source.title || new URL(source.uri).hostname}</span>
                </a>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Target, Send, Loader2, Sparkles, Copy, Check, Bot, Phone, Mail, Award, Globe, Linkedin, Twitter, Facebook, Instagram, Youtube, Link as LinkIcon, Zap, TrendingUp, DollarSign, Newspaper, Edit3, Bookmark, ShieldCheck, MapPin, Briefcase, UserPlus, Search, FileText, UserSearch, Briefcase as BriefcaseIcon, PlusCircle, CheckCircle } from 'lucide-react';
import { Company, Pitch, Job, SavedJob } from '../types';
import { generatePitch } from '../services/geminiService';

interface IntelligencePaneProps {
  company: Company | null;
  onToggleSave: () => void;
  isSaved: boolean;
  onTrackJob: (job: Job) => void;
  savedJobs: SavedJob[];
}

type Tab = 'overview' | 'insights' | 'jobs' | 'outreach';
type PitchFormat = 'email' | 'linkedin_connect' | 'linkedin_inmail';

export const IntelligencePane: React.FC<IntelligencePaneProps> = ({ 
    company, 
    onToggleSave, 
    isSaved,
    onTrackJob,
    savedJobs 
}) => {
  const [activeTab, setActiveTab] = useState<Tab>('overview');
  const [skills, setSkills] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedPitches, setGeneratedPitches] = useState<Pitch[]>([]);
  const [activePitchIndex, setActivePitchIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [pitchFormat, setPitchFormat] = useState<PitchFormat>('email');

  // Outreach Context State
  const [outreachContext, setOutreachContext] = useState<'sales' | 'job_application'>('sales');
  const [targetJobTitle, setTargetJobTitle] = useState('');

  React.useEffect(() => {
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
    setActiveTab('overview');
    // Default to 'jobs' tab if company has open roles and we are in that mindset? No, Overview is safer.
  }, [company?.id]);

  const handleFormatChange = (format: PitchFormat) => {
    setPitchFormat(format);
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
  };

  const handleGenerate = async () => {
    if (!company || !skills) return;

    setIsGenerating(true);
    setGeneratedPitches([]);
    setActivePitchIndex(0);

    try {
      const signalContext = company.signals.map(s => `${s.type}: ${s.text}`);

      const results = await generatePitch({
        companyName: company.name,
        industry: company.industry,
        userSkills: skills,
        tone: 'Professional',
        companySignals: signalContext,
        format: pitchFormat,
        context: outreachContext,
        jobTitle: targetJobTitle
      });
      setGeneratedPitches(results);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const getSignalIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('fund') || t.includes('money')) return <DollarSign className="w-3 h-3 text-emerald-500" />;
    if (t.includes('hir') || t.includes('team') || t.includes('growth')) return <TrendingUp className="w-3 h-3 text-blue-500" />;
    if (t.includes('news') || t.includes('press')) return <Newspaper className="w-3 h-3 text-purple-500" />;
    if (t.includes('loc') || t.includes('hq')) return <MapPin className="w-3 h-3 text-orange-500" />;
    return <ShieldCheck className="w-3 h-3 text-accent" />;
  };

  const getSocialLinks = () => {
    if (!company || !company.socials || company.socials === 'N/A' || company.socials === 'None') return [];

    return company.socials
      .split(/[\s,\n]+/)
      .map(s => s.trim())
      .filter(s => s.length > 0 && !s.toLowerCase().includes('n/a'))
      .map((rawLink, index) => {
        let url = rawLink.replace(/[\[\]()]/g, '');
        if (!url.startsWith('http')) url = `https://${url}`;
        if (!url.includes('.') || url.length < 8) return null;

        let icon = <LinkIcon className="w-4 h-4" />;
        const lowerUrl = url.toLowerCase();

        if (lowerUrl.includes('linkedin')) icon = <Linkedin className="w-4 h-4" />;
        else if (lowerUrl.includes('twitter') || lowerUrl.includes('x.com')) icon = <Twitter className="w-4 h-4" />;
        else if (lowerUrl.includes('facebook')) icon = <Facebook className="w-4 h-4" />;
        else if (lowerUrl.includes('instagram')) icon = <Instagram className="w-4 h-4" />;
        else if (lowerUrl.includes('youtube')) icon = <Youtube className="w-4 h-4" />;

        return { url, icon, key: index };
      })
      .filter((link): link is { url: string; icon: React.ReactElement; key: number } => link !== null);
  };

  if (!company) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-neutral-400 select-none bg-neutral-50/50 dark:bg-black/20">
         <div className="max-w-md p-8">
            <div className="flex items-center gap-3 mb-6">
                <div className="p-3 bg-accent/10 rounded-xl">
                    <Target className="w-8 h-8 text-accent" />
                </div>
                <div>
                    <h2 className="text-xl font-bold text-neutral-900 dark:text-white">Welcome to Recon</h2>
                    <p className="text-sm text-neutral-500">Intelligence Suite for Lead Generation</p>
                </div>
            </div>

            <div className="space-y-4">
                <div className="flex items-start gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 shadow-sm">
                    <div className="mt-1 p-1.5 bg-blue-500/10 rounded-lg">
                        <Search className="w-4 h-4 text-blue-500" />
                    </div>
                    <div>
                        <h4 className="text-sm font-bold text-neutral-900 dark:text-white">1. Discover</h4>
                        <p className="text-xs text-neutral-500 mt-1">Search by Industry, City or Role (e.g., "Copywriter in Mumbai") to find leads.</p>
                    </div>
                </div>

                 <div className="flex items-start gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 shadow-sm">
                    <div className="mt-1 p-1.5 bg-purple-500/10 rounded-lg">
                        <FileText className="w-4 h-4 text-purple-500" />
                    </div>
                    <div>
                        <h4 className="text-sm font-bold text-neutral-900 dark:text-white">2. Analyze & Track Jobs</h4>
                        <p className="text-xs text-neutral-500 mt-1">View open roles, verified contact info, and track your application pipeline.</p>
                    </div>
                </div>

                 <div className="flex items-start gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 shadow-sm">
                    <div className="mt-1 p-1.5 bg-green-500/10 rounded-lg">
                        <Send className="w-4 h-4 text-green-500" />
                    </div>
                    <div>
                        <h4 className="text-sm font-bold text-neutral-900 dark:text-white">3. Outreach</h4>
                        <p className="text-xs text-neutral-500 mt-1">Generate AI-personalized emails or job applications tailored to the company.</p>
                    </div>
                </div>
            </div>
         </div>
      </div>
    );
  }

  const socialLinks = getSocialLinks();
  const currentPitch = generatedPitches[activePitchIndex];

  // Helper to check if a job is tracked
  const isJobTracked = (jobId: string) => savedJobs.some(j => j.id === jobId);

  return (
    <div className="h-full flex flex-col bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-white/10 shadow-glass overflow-hidden">

      {/* Header */}
      <div className="p-6 border-b border-neutral-200 dark:border-white/5 bg-neutral-50/50 dark:bg-black/20">
         <div className="flex justify-between items-start mb-4">
             <div>
                 <h2 className="text-xl font-bold text-neutral-900 dark:text-white tracking-tight">{company.name}</h2>
                 <div className="flex items-center gap-2 text-xs text-neutral-500 mt-1">
                     <Briefcase className="w-3 h-3" />
                     <span>{company.industry}</span>
                     <span className="text-neutral-300 dark:text-neutral-700">•</span>
                     <MapPin className="w-3 h-3" />
                     <span>{company.location || "Unknown Location"}</span>
                 </div>
             </div>

             <button 
                onClick={onToggleSave}
                className={`p-2 rounded-lg border transition-all ${isSaved ? 'bg-accent/10 border-accent text-accent' : 'bg-white dark:bg-neutral-800 border-neutral-200 dark:border-white/10 text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                title={isSaved ? "Remove Company" : "Save Company"}
             >
                 <Bookmark className={`w-4 h-4 ${isSaved ? 'fill-accent' : ''}`} />
             </button>
         </div>

         {/* Stats Bar */}
         <div className="flex items-center gap-4">
             <div className="px-3 py-1.5 rounded-md bg-neutral-100 dark:bg-white/5 border border-neutral-200 dark:border-white/5 flex items-center gap-2">
                 <Zap className="w-3 h-3 text-amber-500" />
                 <span className="text-xs font-bold text-neutral-700 dark:text-neutral-300">Match: {company.hotScore}%</span>
             </div>
             <div className="flex gap-2">
                 {socialLinks.map(link => (
                     <a key={link.key} href={link.url} target="_blank" rel="noreferrer" className="p-1.5 rounded-md hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-400 hover:text-accent transition-colors">
                        {link.icon}
                     </a>
                 ))}
                 {company.website !== 'N/A' && (
                     <a href={company.website.startsWith('http') ? company.website : `https://${company.website}`} target="_blank" rel="noreferrer" className="p-1.5 rounded-md hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-400 hover:text-accent transition-colors">
                        <Globe className="w-4 h-4" />
                     </a>
                 )}
             </div>
         </div>
      </div>

      {/* Navigation Tabs */}
      <div className="flex border-b border-neutral-200 dark:border-white/5">
          {['overview', 'insights', 'jobs', 'outreach'].map((tab) => (
             <button 
                key={tab}
                onClick={() => setActiveTab(tab as Tab)} 
                className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-all border-b-2 
                    ${activeTab === tab 
                        ? 'border-accent text-accent bg-accent/5' 
                        : 'border-transparent text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
             >
                {tab}
             </button>
          ))}
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto p-6 bg-neutral-50/30 dark:bg-neutral-900/30">

        {/* TAB: OVERVIEW */}
        {activeTab === 'overview' && (
            <div className="space-y-6 animate-fade-in">
                <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                    <h3 className="text-xs font-bold text-neutral-500 uppercase mb-3">Company Overview</h3>
                    <p className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed">
                        {company.description}
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                        <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <Award className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Hero Product</span>
                        </div>
                        <p className="text-sm font-medium text-neutral-900 dark:text-white">{company.heroProduct}</p>
                    </div>
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                         <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <Target className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Identified Needs</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {company.needs.map((need, i) => (
                                <span key={i} className="px-2 py-1 rounded text-[10px] font-bold bg-neutral-100 dark:bg-white/10 text-neutral-600 dark:text-neutral-300">
                                    {need}
                                </span>
                            ))}
                        </div>
                    </div>
                </div>

                {company.hiringCulture && (
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                        <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <UserSearch className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Hiring Culture</span>
                        </div>
                        <p className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed">
                            {company.hiringCulture}
                        </p>
                    </div>
                )}
            </div>
        )}

        {/* TAB: INSIGHTS (EVIDENCE) */}
        {activeTab === 'insights' && (
             <div className="space-y-4 animate-fade-in">
                {company.signals.length === 0 ? (
                    <div className="text-center py-10 text-neutral-500">
                        <p className="text-sm">No specific insights detected.</p>
                    </div>
                ) : (
                    company.signals.map((signal, idx) => (
                        <div key={idx} className="flex gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 items-start">
                             <div className="mt-1 p-2 rounded-lg bg-neutral-50 dark:bg-white/5">
                                 {getSignalIcon(signal.type)}
                             </div>
                             <div>
                                 <div className="flex items-center gap-2 mb-1">
                                     <span className="text-xs font-bold uppercase text-neutral-900 dark:text-white">{signal.type}</span>
                                     <span className={`text-[9px] px-1.5 py-0.5 rounded ${signal.confidence === 'High' ? 'bg-green-500/10 text-green-500' : 'bg-neutral-500/10 text-neutral-500'}`}>
                                         {signal.confidence} Confidence
                                     </span>
                                 </div>
                                 <p className="text-sm text-neutral-600 dark:text-neutral-400 leading-snug">{signal.text}</p>
                             </div>
                        </div>
                    ))
                )}
                 <div className="p-4 rounded-xl bg-amber-50/50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-500/20 text-xs text-amber-800 dark:text-amber-500 leading-relaxed">
                    <strong className="block mb-1">AI Analysis:</strong>
                    {company.scoreReasoning || "Automated assessment based on visible digital footprint and relevance."}
                 </div>
             </div>
        )}

        {/* TAB: JOBS */}
        {activeTab === 'jobs' && (
            <div className="space-y-4 animate-fade-in">
                {(!company.openRoles || company.openRoles.length === 0) ? (
                    <div className="text-center py-12 text-neutral-500 flex flex-col items-center">
                        <BriefcaseIcon className="w-10 h-10 mb-3 opacity-30" />
                        <p className="text-sm font-medium">No open roles detected.</p>
                        <p className="text-xs opacity-70 mt-1">Try checking their Careers page directly.</p>
                    </div>
                ) : (
                    <div className="grid gap-3">
                        {company.openRoles.map((role, idx) => {
                           const tracked = isJobTracked(role.id);
                           return (
                            <div key={idx} className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-white/5 hover:border-accent/30 transition-all shadow-sm">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <h4 className="font-bold text-neutral-900 dark:text-white text-sm">{role.title}</h4>
                                        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-neutral-500 mt-1.5">
                                            <span className="flex items-center gap-1"><MapPin className="w-3 h-3"/> {role.location}</span>
                                            {role.type && <span className="bg-neutral-100 dark:bg-white/5 px-1.5 py-0.5 rounded">{role.type}</span>}
                                            {role.salary && <span className="text-emerald-600 dark:text-emerald-400 font-medium">{role.salary}</span>}
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        <button 
                                            onClick={() => {
                                                setOutreachContext('job_application');
                                                setTargetJobTitle(role.title);
                                                setActiveTab('outreach');
                                            }}
                                            className="p-2 text-neutral-400 hover:text-accent hover:bg-accent/10 rounded-lg transition-colors"
                                            title="Draft Application"
                                        >
                                            <Send className="w-4 h-4" />
                                        </button>
                                        <button 
                                            onClick={() => onTrackJob(role)}
                                            className={`p-2 rounded-lg transition-colors border ${tracked ? 'bg-green-500/10 border-green-500 text-green-500' : 'bg-transparent border-neutral-200 dark:border-white/10 text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                                            title={tracked ? "Tracked" : "Track Role"}
                                        >
                                            {tracked ? <CheckCircle className="w-4 h-4" /> : <PlusCircle className="w-4 h-4" />}
                                        </button>
                                    </div>
                                </div>
                                {role.link && (
                                     <a href={role.link} target="_blank" rel="noreferrer" className="mt-3 text-xs text-accent hover:underline inline-flex items-center gap-1">
                                         View Full Listing <ExternalLink className="w-3 h-3" />
                                     </a>
                                )}
                            </div>
                           );
                        })}
                    </div>
                )}
            </div>
        )}

        {/* TAB: OUTREACH (COMMS) */}
        {activeTab === 'outreach' && (
            <div className="h-full flex flex-col animate-fade-in">

                {/* Context Switcher */}
                <div className="flex items-center justify-between mb-4">
                     <div className="flex p-1 bg-neutral-100 dark:bg-neutral-800/50 rounded-lg border border-neutral-200 dark:border-white/5">
                        <button
                            onClick={() => { setOutreachContext('sales'); setTargetJobTitle(''); }}
                            className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${outreachContext === 'sales' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white' : 'text-neutral-500'}`}
                        >
                            Sales Pitch
                        </button>
                        <button
                            onClick={() => { setOutreachContext('job_application'); }}
                            className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${outreachContext === 'job_application' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white' : 'text-neutral-500'}`}
                        >
                            Job Application
                        </button>
                     </div>
                     {outreachContext === 'job_application' && (
                         <input 
                            type="text" 
                            value={targetJobTitle}
                            onChange={(e) => setTargetJobTitle(e.target.value)}
                            placeholder="Target Role..."
                            className="bg-transparent border-b border-neutral-200 dark:border-white/10 px-2 py-1 text-xs text-right focus:outline-none focus:border-accent w-32"
                         />
                     )}
                </div>

                <div className="flex flex-wrap items-center gap-2 mb-4">
                    <button 
                        onClick={() => handleFormatChange('email')}
                        className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 border border-transparent ${pitchFormat === 'email' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white border-neutral-200 dark:border-white/5' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                    >
                        <Mail className="w-3.5 h-3.5" />
                        Email
                    </button>
                    <button 
                        onClick={() => handleFormatChange('linkedin_inmail')}
                        className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 border border-transparent ${pitchFormat === 'linkedin_inmail' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white border-neutral-200 dark:border-white/5' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                    >
                        <Linkedin className="w-3.5 h-3.5" />
                        InMail
                    </button>
                    <button 
                        onClick={() => handleFormatChange('linkedin_connect')}
                        className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 border border-transparent ${pitchFormat === 'linkedin_connect' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white border-neutral-200 dark:border-white/5' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                    >
                        <UserPlus className="w-3.5 h-3.5" />
                        Connect
                    </button>
                </div>

                <div className="mb-4">
                    <label className="text-xs font-bold text-neutral-500 uppercase mb-2 block">Your Offer / Skills</label>
                    <div className="flex gap-2">
                        <input 
                            type="text" 
                            value={skills}
                            onChange={(e) => setSkills(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleGenerate()}
                            placeholder={outreachContext === 'job_application' ? "e.g. 5 yrs Exp in React, UI Design" : "e.g. SEO services for e-commerce"} 
                            className="flex-1 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-white/10 rounded-lg px-3 py-2 text-sm text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent"
                        />
                        <button 
                            onClick={handleGenerate}
                            disabled={!skills || isGenerating}
                            className={`px-4 rounded-lg bg-accent text-white hover:bg-accent-glow disabled:opacity-50 transition-colors shadow-sm`}
                        >
                            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                        </button>
                    </div>
                </div>

                {generatedPitches.length > 0 ? (
                    <div className="flex-1 flex flex-col bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-white/10 overflow-hidden">
                        <div className="flex border-b border-neutral-200 dark:border-white/5">
                            {generatedPitches.map((p, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => { setActivePitchIndex(idx); setIsEditing(false); }}
                                    className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wider transition-colors ${idx === activePitchIndex ? 'text-accent bg-accent/5' : 'text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300'}`}
                                >
                                    {p.angle}
                                </button>
                            ))}
                        </div>
                        <div className="flex-1 p-4 overflow-y-auto">
                             {pitchFormat !== 'linkedin_connect' && (
                                <div className="mb-3">
                                    <div className="flex justify-between items-center mb-1">
                                        <span className="text-[10px] font-bold text-neutral-400 uppercase">Subject</span>
                                    </div>
                                    {isEditing ? (
                                        <input 
                                            type="text"
                                            value={currentPitch.subject}
                                            onChange={(e) => {
                                                const newPitches = [...generatedPitches];
                                                newPitches[activePitchIndex].subject = e.target.value;
                                                setGeneratedPitches(newPitches);
                                            }}
                                            className="w-full bg-neutral-50 dark:bg-neutral-900/50 border border-neutral-200 dark:border-white/10 rounded px-2 py-1.5 text-sm font-medium text-neutral-900 dark:text-white focus:outline-none focus:border-accent"
                                        />
                                    ) : (
                                        <p className="text-sm font-medium text-neutral-900 dark:text-white select-all">{currentPitch.subject}</p>
                                    )}
                                    <div className="h-px bg-neutral-100 dark:bg-white/5 my-3"></div>
                                </div>
                             )}

                             {isEditing ? (
                                <textarea 
                                    value={currentPitch.body}
                                    onChange={(e) => {
                                        const newPitches = [...generatedPitches];
                                        newPitches[activePitchIndex].body = e.target.value;
                                        setGeneratedPitches(newPitches);
                                    }}
                                    className="w-full h-40 bg-transparent resize-none focus:outline-none text-sm leading-relaxed p-0 text-neutral-600 dark:text-neutral-300"
                                />
                             ) : (
                                <p className="text-sm text-neutral-600 dark:text-neutral-300 whitespace-pre-wrap leading-relaxed select-all">
                                    {currentPitch.body}
                                </p>
                             )}
                        </div>
                         <div className="p-2 border-t border-neutral-200 dark:border-white/5 bg-neutral-50 dark:bg-black/20 flex justify-between items-center">
                             <div className="flex gap-2 items-center">
                                <button onClick={() => setIsEditing(!isEditing)} className={`p-2 rounded transition-colors ${isEditing ? 'bg-accent/10 text-accent' : 'hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-500'}`} title={isEditing ? "Finish Editing" : "Edit Text"}>
                                    <Edit3 className="w-4 h-4" />
                                </button>
                                {pitchFormat === 'linkedin_connect' && (
                                    <span className={`text-[10px] font-mono ${currentPitch.body.length > 300 ? 'text-red-500 font-bold' : 'text-neutral-400'}`}>
                                        {currentPitch.body.length}/300
                                    </span>
                                )}
                             </div>
                             <div className="flex gap-2">
                                {pitchFormat === 'email' && (
                                    <a href={`mailto:${company.email}?subject=${encodeURIComponent(currentPitch.subject)}&body=${encodeURIComponent(currentPitch.body)}`} className="p-2 rounded hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-600 dark:text-white" title="Open Mail Client">
                                        <Mail className="w-4 h-4" />
                                    </a>
                                )}
                                <button onClick={() => copyToClipboard((pitchFormat === 'email' || pitchFormat === 'linkedin_inmail') ? `Subject: ${currentPitch.subject}\n\n${currentPitch.body}` : currentPitch.body)} className="flex items-center gap-2 px-3 py-1.5 rounded bg-accent text-white shadow-sm hover:bg-accent-glow text-xs font-bold uppercase transition-colors">
                                    {copied ? <Check className="w-3 h-3" /> : <Copy className="w-3 h-3" />}
                                    <span>{copied ? 'Copied' : 'Copy'}</span>
                                </button>
                             </div>
                        </div>
                    </div>
                ) : (
                     <div className="flex-1 flex flex-col items-center justify-center text-neutral-400 opacity-50 border-2 border-dashed border-neutral-200 dark:border-white/5 rounded-xl">
                        <Bot className="w-6 h-6 mb-2" />
                        <span className="text-xs">Enter skills to generate messages</span>
                     </div>
                )}
            </div>
        )}

      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Header } from './components/Header';
import { SearchPane } from './components/SearchPane';
import { IntelligencePane } from './components/IntelligencePane';
import { Sidebar } from './components/Sidebar';
import { VoiceMode } from './components/VoiceMode';
import { Company, SearchMode, SearchParams, Source, Job, SavedJob } from './types';
import { findLeads } from './services/geminiService';
import { Menu, ChevronRight, X, Mic } from 'lucide-react';

// Simple Toast Component
const Toast = ({ message, type, onClose }: { message: string, type: 'success' | 'error' | 'info', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className={`
        flex items-center gap-3 px-4 py-3 rounded-xl shadow-lg shadow-black/20 border backdrop-blur-md animate-fade-in-up
        ${type === 'error' ? 'bg-red-500/90 text-white border-red-500' : 
          type === 'success' ? 'bg-emerald-500/90 text-white border-emerald-500' : 
          'bg-neutral-800/90 text-white border-neutral-700'}
    `}>
      <span className="text-sm font-medium">{message}</span>
      <button onClick={onClose} className="opacity-70 hover:opacity-100 transition-opacity"><X size={14} /></button>
    </div>
  );
};

const App: React.FC = () => {
  // Initialize theme based on system preference
  const [isDarkMode, setIsDarkMode] = useState(() => {
    if (typeof window !== 'undefined') {
        return window.matchMedia('(prefers-color-scheme: dark)').matches;
    }
    return true;
  });

  const [toasts, setToasts] = useState<{ id: number; message: string; type: 'success' | 'error' | 'info' }[]>([]);

  const [selectedCompanyId, setSelectedCompanyId] = useState<string | null>(null);

  // Voice Mode State
  const [isVoiceModeActive, setIsVoiceModeActive] = useState(false);

  // State for Live Results vs Saved Targets
  const [searchResults, setSearchResults] = useState<Company[]>([]);
  const [searchSources, setSearchSources] = useState<Source[]>([]);

  const [savedCompanies, setSavedCompanies] = useState<Company[]>(() => {
    const saved = localStorage.getItem('recon_saved_targets');
    return saved ? JSON.parse(saved) : [];
  });

  // Job Tracking State
  const [savedJobs, setSavedJobs] = useState<SavedJob[]>(() => {
      const saved = localStorage.getItem('recon_saved_jobs');
      return saved ? JSON.parse(saved) : [];
  });

  // Pre-fetching State
  const [nextBatch, setNextBatch] = useState<{ leads: Company[], sources: Source[] } | null>(null);
  const [isPrefetching, setIsPrefetching] = useState(false);

  const [isSearching, setIsSearching] = useState(false);
  const [showMobileSidebar, setShowMobileSidebar] = useState(false);

  const currentSearchParamsRef = useRef<SearchParams | null>(null);

  // Abort Controller Ref to handle cancellation
  const abortControllerRef = useRef<AbortController | null>(null);

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now(), message, type }]);
  };

  const removeToast = (id: number) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  // Initialize theme
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
      document.documentElement.classList.remove('light');
    } else {
      document.documentElement.classList.remove('dark');
      document.documentElement.classList.add('light');
    }
  }, [isDarkMode]);

  // Persist Data
  useEffect(() => {
    localStorage.setItem('recon_saved_targets', JSON.stringify(savedCompanies));
  }, [savedCompanies]);

  useEffect(() => {
    localStorage.setItem('recon_saved_jobs', JSON.stringify(savedJobs));
  }, [savedJobs]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Mouse tracking
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    const x = e.clientX;
    const y = e.clientY;
    document.documentElement.style.setProperty('--mouse-x', `${x}px`);
    document.documentElement.style.setProperty('--mouse-y', `${y}px`);
  }, []);

  // BACKGROUND TASK: Prefetch the next 5 leads
  const prefetchNextBatch = async (currentResults: Company[], params: SearchParams) => {
    if (params.mode === 'lookup') return; // Don't prefetch for single lookups

    setIsPrefetching(true);
    try {
        const excludeNames = [...currentResults.map(c => c.name), ...savedCompanies.map(c => c.name)];
        const nextParams = { ...params, excludeNames };

        const result = await findLeads(nextParams, abortControllerRef.current?.signal);
        setNextBatch(result);
    } catch (error: any) {
        if (error.name !== 'AbortError') {
            console.log("Prefetch suspended or failed (non-critical).");
        }
    } finally {
        setIsPrefetching(false);
    }
  };

  const handleSearch = async (mode: SearchMode, p1: string, p2: string) => {
    // 1. STOP EVERYTHING
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
    abortControllerRef.current = new AbortController();

    setIsSearching(true);
    setSearchResults([]); 
    setSearchSources([]);
    setNextBatch(null); 
    setSelectedCompanyId(null);

    // MAPPING ARGS TO PARAMS
    // Discovery: p1=Industry, p2=City
    // Jobs: p1=Role, p2=City
    // Lookup: p1=CompanyName, p2=City

    const params: SearchParams = {
        mode,
        industry: mode === 'discovery' ? p1 : undefined,
        city: p2,
        role: mode === 'jobs' ? p1 : undefined,
        companyName: mode === 'lookup' ? p1 : undefined,
        excludeNames: savedCompanies.map(c => c.name)
    };
    currentSearchParamsRef.current = params;

    try {
      const { leads, sources } = await findLeads(params, abortControllerRef.current.signal);
      setSearchResults(leads);
      setSearchSources(sources);

      if (leads.length === 0) {
        addToast("No leads found. Try a broader search.", "info");
      } else {
        prefetchNextBatch(leads, params);
      }
    } catch (error: any) {
      if (error.name === 'AbortError') {
          console.log("Search aborted by user.");
      } else {
          console.error("Search failed", error);
          addToast(error.message || "Could not find leads.", "error");
      }
    } finally {
      if (!abortControllerRef.current?.signal.aborted) {
          setIsSearching(false);
      }
    }
  };

  const handleLoadMore = async () => {
    if (!currentSearchParamsRef.current || currentSearchParamsRef.current.mode === 'lookup') return;

    // STRATEGY: Instant Load if buffer is ready
    if (nextBatch && nextBatch.leads.length > 0) {
        const batchLeads = nextBatch.leads;
        const batchSources = nextBatch.sources;

        setNextBatch(null); // Clear buffer immediately

        setSearchResults(prev => {
            const updated = [...prev, ...batchLeads];
            prefetchNextBatch(updated, currentSearchParamsRef.current!); 
            return updated;
        });
        setSearchSources(prev => {
            // Merge and dedupe sources
            const combined = [...prev, ...batchSources];
            return combined.filter((v, i, a) => a.findIndex(t => (t.uri === v.uri)) === i);
        });
        return;
    }

    // Fallback
    setIsSearching(true);
    try {
      const excludeNames = [...searchResults.map(c => c.name), ...savedCompanies.map(c => c.name)];
      const params: SearchParams = { ...currentSearchParamsRef.current, excludeNames };

      const { leads, sources } = await findLeads(params, abortControllerRef.current?.signal);

      if (leads.length === 0) {
        addToast("No more unique leads found in this area.", "info");
      } else {
        setSearchResults(prev => {
            const updated = [...prev, ...leads];
            prefetchNextBatch(updated, currentSearchParamsRef.current!);
            return updated;
        });
        setSearchSources(prev => {
             const combined = [...prev, ...sources];
             return combined.filter((v, i, a) => a.findIndex(t => (t.uri === v.uri)) === i);
        });
      }
    } catch (error: any) {
       if (error.name !== 'AbortError') {
          addToast(error.message || "Failed to load more leads.", "error");
       }
    } finally {
      setIsSearching(false);
    }
  };

  const toggleSaveCompany = (company: Company) => {
    if (savedCompanies.some(c => c.id === company.id)) {
        // Remove
        setSavedCompanies(prev => prev.filter(c => c.id !== company.id));
        addToast("Company removed from saved list", "info");
    } else {
        // Add
        const newCompany = { ...company, status: 'Saved' as const };
        setSavedCompanies(prev => [newCompany, ...prev]);
        addToast("Company saved successfully", "success");
    }
  };

  const trackJob = (job: Job, company: Company) => {
      const existing = savedJobs.find(j => j.id === job.id);
      if (existing) {
          addToast("Job already tracked.", "info");
          return;
      }
      const newJob: SavedJob = {
          ...job,
          companyId: company.id,
          companyName: company.name,
          status: 'Saved'
      };
      setSavedJobs(prev => [newJob, ...prev]);

      // Auto-save company if not saved? Let's leave them separate but user likely wants company saved too.
      // Optionally toggleSaveCompany(company) if not present.
      if (!savedCompanies.some(c => c.id === company.id)) {
          toggleSaveCompany(company);
      }

      addToast("Job added to pipeline.", "success");
  };

  const updateJobStatus = (jobId: string, status: 'Saved' | 'Applied' | 'Interviewing' | 'Offer') => {
      setSavedJobs(prev => prev.map(j => j.id === jobId ? { ...j, status } : j));
  };

  const removeJobs = (jobIds: string[]) => {
      setSavedJobs(prev => prev.filter(j => !jobIds.includes(j.id)));
      addToast("Jobs removed from pipeline.", "info");
  };

  const removeMultipleSavedCompanies = (ids: string[]) => {
    setSavedCompanies(prev => prev.filter(c => !ids.includes(c.id)));
    if (selectedCompanyId && ids.includes(selectedCompanyId)) {
        setSelectedCompanyId(null);
    }
    addToast(`Deleted ${ids.length} companies`, "info");
  };

  const selectedCompany = 
    searchResults.find(c => c.id === selectedCompanyId) || 
    savedCompanies.find(c => c.id === selectedCompanyId) || 
    null;

  return (
    <div 
      onMouseMove={handleMouseMove}
      className="h-screen bg-neutral-50 dark:bg-neutral-950 transition-colors duration-400 overflow-hidden flex flex-col relative"
    >
      {/* Voice Mode Overlay */}
      <VoiceMode 
        isActive={isVoiceModeActive} 
        onClose={() => setIsVoiceModeActive(false)} 
        contextCompany={selectedCompany} 
      />

      {/* Floating Action Button for Voice - High Z-Index to Ensure Visibility */}
      <div className="fixed bottom-6 right-6 z-[100] flex flex-col items-end space-y-4 pointer-events-none">
         {/* Toast Area */}
         <div className="flex flex-col gap-2 pointer-events-auto items-end">
            {toasts.map(toast => (
                <Toast key={toast.id} {...toast} onClose={() => removeToast(toast.id)} />
            ))}
         </div>

         {/* FAB */}
         <button
            onClick={() => setIsVoiceModeActive(true)}
            className="pointer-events-auto group relative flex items-center justify-center w-14 h-14 rounded-full bg-gradient-to-tr from-accent to-accent-glow text-white shadow-lg shadow-accent/40 hover:scale-110 hover:shadow-accent/60 transition-all duration-300 ease-out"
            aria-label="Start Voice Assistant"
         >
            <div className="absolute inset-0 rounded-full bg-white opacity-0 group-hover:opacity-20 animate-ping duration-1000"></div>
            <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-accent to-accent-glow opacity-80 blur-md"></div>
            <Mic className="w-6 h-6 relative z-10 drop-shadow-sm" />
         </button>
      </div>

      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
        <div className={`absolute -top-[20%] -left-[10%] w-[50%] h-[50%] rounded-full blur-[120px] transition-opacity duration-1000 ${isDarkMode ? 'bg-accent/5' : 'bg-accent/10'}`}></div>
        <div className="absolute inset-0 spotlight-bg opacity-100 transition-opacity duration-500"></div>
      </div>

      <div className="relative z-10 flex flex-col h-full">
        <Header 
            isDarkMode={isDarkMode} 
            toggleTheme={toggleTheme} 
            onVoiceToggle={() => setIsVoiceModeActive(true)}
        />

        <main className="flex-1 w-full max-w-screen-2xl mx-auto flex overflow-hidden">

          <div className="hidden lg:block w-72 h-full shrink-0">
             <Sidebar 
                savedCompanies={savedCompanies}
                savedJobs={savedJobs}
                onSelectCompany={(c) => setSelectedCompanyId(c.id)}
                selectedCompanyId={selectedCompanyId}
                onRemoveCompanies={removeMultipleSavedCompanies}
                onUpdateJobStatus={updateJobStatus}
                onRemoveJobs={removeJobs}
             />
          </div>

           {showMobileSidebar && (
              <div className="fixed inset-0 z-50 lg:hidden flex">
                  <div className="w-72 h-full bg-neutral-900 shadow-2xl animate-fade-in">
                     <Sidebar 
                        savedCompanies={savedCompanies}
                        savedJobs={savedJobs}
                        onSelectCompany={(c) => { setSelectedCompanyId(c.id); setShowMobileSidebar(false); }}
                        selectedCompanyId={selectedCompanyId}
                        onRemoveCompanies={removeMultipleSavedCompanies}
                        onUpdateJobStatus={updateJobStatus}
                        onRemoveJobs={removeJobs}
                     />
                  </div>
                  <div className="flex-1 bg-black/50 backdrop-blur-sm" onClick={() => setShowMobileSidebar(false)}></div>
              </div>
           )}

          <div className="flex-1 flex flex-col lg:flex-row min-w-0">

            <div className="lg:hidden p-2 border-b border-neutral-200 dark:border-white/10 flex items-center justify-between bg-neutral-100/50 dark:bg-neutral-900/50">
               <button onClick={() => setShowMobileSidebar(true)} className="flex items-center gap-2 text-xs font-bold uppercase text-neutral-500">
                  <Menu className="w-4 h-4" /> Open Saved List
               </button>
               <span className="text-[10px] text-accent font-mono">{savedCompanies.length} SAVED</span>
            </div>

            <div className={`
                flex-1 flex flex-col h-full min-w-0 border-r border-neutral-200 dark:border-white/5 bg-white/30 dark:bg-neutral-950/30
                ${selectedCompanyId ? 'hidden lg:flex' : 'flex'} 
            `}>
              <div className="p-4 h-full">
                <SearchPane 
                    companies={searchResults} 
                    sources={searchSources}
                    selectedCompanyId={selectedCompanyId}
                    onSelectCompany={setSelectedCompanyId}
                    onSearch={handleSearch}
                    onLoadMore={handleLoadMore}
                    isSearching={isSearching}
                />
              </div>
            </div>

            <div className={`
                lg:w-[600px] xl:w-[700px] h-full flex-col bg-white/50 dark:bg-neutral-900/50 backdrop-blur-md
                ${selectedCompanyId ? 'flex fixed inset-0 z-40 lg:static lg:z-auto' : 'hidden lg:flex'}
            `}>
               {selectedCompanyId && (
                  <div className="lg:hidden p-4 border-b border-neutral-200 dark:border-white/10 flex items-center justify-between bg-white dark:bg-neutral-900">
                      <button 
                          onClick={() => setSelectedCompanyId(null)}
                          className="text-sm font-medium text-neutral-500 flex items-center gap-2"
                      >
                          <ChevronRight className="w-4 h-4 rotate-180" /> Back
                      </button>
                  </div>
               )}

               <div className="flex-1 h-full overflow-hidden p-4">
                  <IntelligencePane 
                      company={selectedCompany} 
                      onToggleSave={() => selectedCompany && toggleSaveCompany(selectedCompany)}
                      isSaved={!!selectedCompany && savedCompanies.some(c => c.id === selectedCompany.id)}
                      onTrackJob={(job) => selectedCompany && trackJob(job, selectedCompany)}
                      savedJobs={savedJobs}
                  />
               </div>
            </div>

          </div>
        </main>
      </div>
    </div>
  );
};

