import React, { useState } from 'react';
import { Archive, Download, Trash2, Crosshair, CheckSquare, Square, Briefcase } from 'lucide-react';
import { Company, SavedJob } from '../types';

interface SidebarProps {
  savedCompanies: Company[];
  savedJobs: SavedJob[];
  onSelectCompany: (company: Company) => void;
  selectedCompanyId: string | null;
  onRemoveCompanies: (ids: string[]) => void;
  onUpdateJobStatus: (id: string, status: 'Saved' | 'Applied' | 'Interviewing' | 'Offer') => void;
  onRemoveJobs: (ids: string[]) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  savedCompanies, 
  savedJobs,
  onSelectCompany, 
  selectedCompanyId,
  onRemoveCompanies,
  onUpdateJobStatus,
  onRemoveJobs
}) => {
  const [view, setView] = useState<'companies' | 'jobs'>('companies');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isSelectionMode, setIsSelectionMode] = useState(false);

  const toggleSelection = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (selectedIds.includes(id)) {
      setSelectedIds(prev => prev.filter(sid => sid !== id));
    } else {
      setSelectedIds(prev => [...prev, id]);
    }
  };

  const toggleSelectionMode = () => {
    if (isSelectionMode) {
      setIsSelectionMode(false);
      setSelectedIds([]);
    } else {
      setIsSelectionMode(true);
    }
  };

  const handleBulkDelete = () => {
    if (view === 'companies') {
        if (window.confirm(`Delete ${selectedIds.length} leads?`)) {
            onRemoveCompanies(selectedIds);
            setSelectedIds([]);
            setIsSelectionMode(false);
        }
    } else {
        if (window.confirm(`Delete ${selectedIds.length} jobs?`)) {
            onRemoveJobs(selectedIds);
            setSelectedIds([]);
            setIsSelectionMode(false);
        }
    }
  };

  const handleExportCSV = () => {
    if (view === 'companies') {
        const targets = isSelectionMode && selectedIds.length > 0
        ? savedCompanies.filter(c => selectedIds.includes(c.id))
        : savedCompanies;

        if (targets.length === 0) return;

        const headers = ['Name', 'Industry', 'Location', 'Website', 'Email', 'Phone', 'Recent Work', 'Hot Score', 'Status'];
        const clean = (text: string) => `"${(text || '').toString().replace(/"/g, '""')}"`;

        const csvContent = [
        headers.join(','),
        ...targets.map(c => [
            clean(c.name),
            clean(c.industry),
            clean(c.location),
            clean(c.website),
            clean(c.email),
            clean(c.phone),
            clean(c.recentWork),
            clean(c.hotScore.toString()),
            clean(c.status)
        ].join(','))
        ].join('\n');

        downloadCSV(csvContent, 'recon_leads');
    } else {
         const targets = isSelectionMode && selectedIds.length > 0
        ? savedJobs.filter(j => selectedIds.includes(j.id))
        : savedJobs;

        if (targets.length === 0) return;

        const headers = ['Title', 'Company', 'Location', 'Type', 'Salary', 'Status', 'Link'];
        const clean = (text: string) => `"${(text || '').toString().replace(/"/g, '""')}"`;

        const csvContent = [
        headers.join(','),
        ...targets.map(j => [
            clean(j.title),
            clean(j.companyName),
            clean(j.location),
            clean(j.type),
            clean(j.salary || ''),
            clean(j.status || 'Saved'),
            clean(j.link || '')
        ].join(','))
        ].join('\n');

        downloadCSV(csvContent, 'recon_jobs');
    }
  };

  const downloadCSV = (content: string, prefix: string) => {
    const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `${prefix}_${new Date().toISOString().slice(0,10)}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleJobClick = (job: SavedJob) => {
      // Find associated company and select it
      const company = savedCompanies.find(c => c.id === job.companyId);
      if (company) {
          onSelectCompany(company);
      }
  };

  return (
    <div className="h-full flex flex-col bg-neutral-50 dark:bg-neutral-900 border-r border-neutral-200 dark:border-white/5">
      {/* View Toggle Header */}
      <div className="p-4 border-b border-neutral-200 dark:border-white/5 bg-neutral-100/50 dark:bg-white/5">
          <div className="flex bg-white dark:bg-neutral-800 rounded-lg p-1 border border-neutral-200 dark:border-white/5 mb-3">
              <button 
                onClick={() => setView('companies')}
                className={`flex-1 flex items-center justify-center gap-2 py-1.5 rounded-md text-[10px] font-bold uppercase transition-all ${view === 'companies' ? 'bg-neutral-100 dark:bg-neutral-700 text-neutral-900 dark:text-white shadow-sm' : 'text-neutral-500'}`}
              >
                  <Archive className="w-3 h-3" /> Leads
              </button>
              <button 
                onClick={() => setView('jobs')}
                className={`flex-1 flex items-center justify-center gap-2 py-1.5 rounded-md text-[10px] font-bold uppercase transition-all ${view === 'jobs' ? 'bg-neutral-100 dark:bg-neutral-700 text-neutral-900 dark:text-white shadow-sm' : 'text-neutral-500'}`}
              >
                  <Briefcase className="w-3 h-3" /> Pipeline
              </button>
          </div>

          <div className="flex justify-between items-center">
            <p className="text-[10px] text-neutral-500 font-medium tracking-wide uppercase">
                {view === 'companies' ? `${savedCompanies.length} Companies` : `${savedJobs.length} Jobs`}
            </p>

            {(view === 'companies' ? savedCompanies.length : savedJobs.length) > 0 && (
                <button 
                    onClick={toggleSelectionMode}
                    className={`p-1.5 rounded transition-colors ${isSelectionMode ? 'text-accent bg-accent/10' : 'text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                    title="Toggle Selection Mode"
                >
                    <CheckSquare className="w-4 h-4" />
                </button>
            )}
          </div>
      </div>

      <div className="flex-1 overflow-y-auto p-2 space-y-2">
        {/* COMPANIES VIEW */}
        {view === 'companies' && (
             savedCompanies.length === 0 ? (
                <div className="h-48 flex flex-col items-center justify-center text-neutral-400 opacity-60">
                    <Crosshair className="w-8 h-8 mb-2 stroke-1" />
                    <span className="text-xs">No saved leads</span>
                </div>
             ) : (
                savedCompanies.map((company) => {
                    const isChecked = selectedIds.includes(company.id);
                    return (
                    <div
                        key={company.id}
                        onClick={() => isSelectionMode ? toggleSelection(company.id, { stopPropagation: () => {} } as any) : onSelectCompany(company)}
                        className={`
                        group relative p-3 rounded-lg cursor-pointer border transition-all duration-200 flex items-center gap-3
                        ${selectedCompanyId === company.id 
                            ? 'bg-white dark:bg-neutral-800 border-accent shadow-sm' 
                            : 'bg-transparent border-transparent hover:bg-neutral-100 dark:hover:bg-neutral-800 hover:border-neutral-200 dark:hover:border-white/10'}
                        `}
                    >
                        {isSelectionMode && (
                        <div 
                            onClick={(e) => toggleSelection(company.id, e)}
                            className={`shrink-0 text-neutral-400 ${isChecked ? 'text-accent' : 'hover:text-neutral-500'}`}
                        >
                            {isChecked ? <CheckSquare className="w-4 h-4" /> : <Square className="w-4 h-4" />}
                        </div>
                        )}

                        <div className="flex-1 min-w-0">
                        <h4 className={`text-xs font-bold truncate ${selectedCompanyId === company.id ? 'text-neutral-900 dark:text-white' : 'text-neutral-600 dark:text-neutral-400'}`}>
                            {company.name}
                        </h4>
                        <div className="flex items-center gap-2 mt-0.5">
                            <span className="text-[10px] text-neutral-400 truncate max-w-[80px]">{company.industry}</span>
                            <div className={`w-1.5 h-1.5 rounded-full ${company.status === 'Contacted' ? 'bg-green-500' : 'bg-amber-500'}`}></div>
                        </div>
                        </div>

                        {!isSelectionMode && (
                        <button
                            onClick={(e) => { e.stopPropagation(); onRemoveCompanies([company.id]); }}
                            className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-500 text-neutral-400 transition-opacity"
                            title="Remove Lead"
                        >
                            <Trash2 className="w-3 h-3" />
                        </button>
                        )}
                    </div>
                    );
                })
             )
        )}

        {/* JOBS VIEW */}
        {view === 'jobs' && (
             savedJobs.length === 0 ? (
                <div className="h-48 flex flex-col items-center justify-center text-neutral-400 opacity-60">
                    <Briefcase className="w-8 h-8 mb-2 stroke-1" />
                    <span className="text-xs">No tracked jobs</span>
                </div>
             ) : (
                 savedJobs.map((job) => {
                     const isChecked = selectedIds.includes(job.id);
                     const statusColors = {
                         'Saved': 'bg-neutral-500',
                         'Applied': 'bg-blue-500',
                         'Interviewing': 'bg-purple-500',
                         'Offer': 'bg-green-500'
                     };

                     return (
                         <div
                            key={job.id}
                            className="group relative p-3 rounded-lg border border-neutral-200 dark:border-white/5 bg-white dark:bg-neutral-800/50 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-all"
                         >
                             <div className="flex items-start gap-3">
                                {isSelectionMode && (
                                    <div 
                                        onClick={(e) => toggleSelection(job.id, e)}
                                        className={`mt-1 shrink-0 text-neutral-400 cursor-pointer ${isChecked ? 'text-accent' : 'hover:text-neutral-500'}`}
                                    >
                                        {isChecked ? <CheckSquare className="w-4 h-4" /> : <Square className="w-4 h-4" />}
                                    </div>
                                )}
                                <div className="flex-1 min-w-0 cursor-pointer" onClick={() => handleJobClick(job)}>
                                    <h4 className="text-xs font-bold text-neutral-900 dark:text-white truncate">{job.title}</h4>
                                    <p className="text-[10px] text-neutral-500 truncate">{job.companyName}</p>
                                    <div className="mt-2 flex items-center justify-between">
                                        <select 
                                            value={job.status || 'Saved'}
                                            onChange={(e) => onUpdateJobStatus(job.id, e.target.value as any)}
                                            onClick={(e) => e.stopPropagation()}
                                            className={`text-[9px] font-bold uppercase rounded px-1.5 py-0.5 border-none outline-none cursor-pointer text-white ${statusColors[job.status || 'Saved'] || 'bg-neutral-500'}`}
                                        >
                                            <option value="Saved" className="text-black">Saved</option>
                                            <option value="Applied" className="text-black">Applied</option>
                                            <option value="Interviewing" className="text-black">Interviewing</option>
                                            <option value="Offer" className="text-black">Offer</option>
                                        </select>
                                    </div>
                                </div>
                                {!isSelectionMode && (
                                    <button
                                        onClick={(e) => { e.stopPropagation(); onRemoveJobs([job.id]); }}
                                        className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-500 text-neutral-400 transition-opacity"
                                        title="Remove Job"
                                    >
                                        <Trash2 className="w-3 h-3" />
                                    </button>
                                )}
                             </div>
                         </div>
                     );
                 })
             )
        )}
      </div>

      {/* Actions Toolbar */}
      {(view === 'companies' ? savedCompanies.length : savedJobs.length) > 0 && (
         <div className="p-3 border-t border-neutral-200 dark:border-white/5 bg-neutral-100/50 dark:bg-black/20 space-y-2">
            {isSelectionMode ? (
               <div className="flex gap-2 animate-fade-in-up">
                  <button
                    onClick={handleBulkDelete}
                    disabled={selectedIds.length === 0}
                    className="flex-1 py-2 rounded-lg bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 text-xs font-bold uppercase disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 transition-colors"
                  >
                    <Trash2 className="w-3 h-3" />
                    <span>Delete ({selectedIds.length})</span>
                  </button>
                  <button
                    onClick={handleExportCSV}
                    disabled={selectedIds.length === 0}
                    className="flex-1 py-2 rounded-lg bg-accent/10 hover:bg-accent/20 text-accent text-xs font-bold uppercase disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 transition-colors"
                  >
                    <Download className="w-3 h-3" />
                    <span>Export ({selectedIds.length})</span>
                  </button>
               </div>
            ) : (
                <button
                    onClick={handleExportCSV}
                    className="w-full py-2 rounded-lg bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-white/10 hover:border-accent hover:text-accent text-neutral-500 dark:text-neutral-400 text-xs font-bold uppercase flex items-center justify-center gap-2 transition-all shadow-sm"
                >
                    <Download className="w-3 h-3" />
                    <span>Export All CSV</span>
                </button>
            )}
         </div>
      )}
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Mic, X, Activity, Volume2, Globe, Wifi } from 'lucide-react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { Company } from '../types';

interface VoiceModeProps {
  isActive: boolean;
  onClose: () => void;
  contextCompany: Company | null;
}

export const VoiceMode: React.FC<VoiceModeProps> = ({ isActive, onClose, contextCompany }) => {
  const [status, setStatus] = useState<'connecting' | 'listening' | 'speaking' | 'error'>('connecting');
  const [volumeLevel, setVolumeLevel] = useState(0);

  // Refs for Audio Handling
  const inputContextRef = useRef<AudioContext | null>(null);
  const outputContextRef = useRef<AudioContext | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const sourceNodeRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sessionPromiseRef = useRef<Promise<any> | null>(null);
  const currentCompanyIdRef = useRef<string | null>(null);
  const audioSourcesRef = useRef<AudioBufferSourceNode[]>([]);

  // Initialize Audio Contexts
  // We use 16kHz for input (Gemini requirement) and 24kHz for output (Gemini high-quality voice)
  const ensureAudioContexts = () => {
    if (!inputContextRef.current) {
      inputContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
    }
    if (!outputContextRef.current) {
      outputContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }

    // Resume if suspended (browser autoplay policy)
    if (inputContextRef.current.state === 'suspended') inputContextRef.current.resume();
    if (outputContextRef.current.state === 'suspended') outputContextRef.current.resume();
  };

  const stopAllAudio = () => {
    audioSourcesRef.current.forEach(source => {
      try { source.stop(); } catch (e) { /* ignore */ }
      try { source.disconnect(); } catch (e) { /* ignore */ }
    });
    audioSourcesRef.current = [];
    if (outputContextRef.current) {
        nextStartTimeRef.current = outputContextRef.current.currentTime;
    }
  };

  // Helper: Base64 to ArrayBuffer
  const decodeAudioData = async (base64: string, ctx: AudioContext): Promise<AudioBuffer> => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    // Convert PCM to AudioBuffer
    const dataInt16 = new Int16Array(bytes.buffer);
    const frameCount = dataInt16.length; 
    const buffer = ctx.createBuffer(1, frameCount, 24000); // 24kHz output from Gemini
    const channelData = buffer.getChannelData(0);

    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i] / 32768.0;
    }
    return buffer;
  };

  // Helper: Float32 to PCM Base64 (16-bit)
  const createPcmData = (data: Float32Array) => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = Math.max(-1, Math.min(1, data[i])) * 32768;
    }
    const bytes = new Uint8Array(int16.buffer);
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  useEffect(() => {
    let mounted = true;

    const startSession = async () => {
      if (!isActive) return;

      try {
        setStatus('connecting');
        ensureAudioContexts();

        const apiKey = (window as any).process?.env?.API_KEY || process.env.API_KEY; 
        if (!apiKey) throw new Error("No API Key");

        const ai = new GoogleGenAI({ apiKey });

        const config = {
          responseModalities: [Modality.AUDIO],
          tools: [{ googleSearch: {} }], // Enable Search for real-time intelligence
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          systemInstruction: `You are Recon's Voice Assistant. Keep responses concise, punchy, and professional. 
          You help users find leads, analyze companies, AND find jobs/roles.

          If the user asks to "find jobs" or "find roles", use Google Search to find current openings.
          If the user is looking at a specific company, focus on that context.

          Do not be verbose. Be helpful and direct.`,
        };

        sessionPromiseRef.current = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-09-2025',
          config,
          callbacks: {
            onopen: async () => {
              if (!mounted) return;
              console.log("Recon Live: Connected");
              setStatus('listening');

              // Start Microphone with Echo Cancellation
              mediaStreamRef.current = await navigator.mediaDevices.getUserMedia({ 
                  audio: {
                      echoCancellation: true,
                      noiseSuppression: true,
                      autoGainControl: true,
                      sampleRate: 16000 
                  }
              });

              if (!inputContextRef.current) return;

              const inputCtx = inputContextRef.current;
              sourceNodeRef.current = inputCtx.createMediaStreamSource(mediaStreamRef.current);
              // Reduced buffer size to 2048 for lower latency (approx 128ms)
              processorRef.current = inputCtx.createScriptProcessor(2048, 1, 1);

              processorRef.current.onaudioprocess = (e) => {
                if (!mounted) return;
                const inputData = e.inputBuffer.getChannelData(0);

                // Visualization
                let sum = 0;
                for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                const rms = Math.sqrt(sum / inputData.length);
                setVolumeLevel(Math.min(1, rms * 5)); 

                // Send to Gemini
                const pcmBase64 = createPcmData(inputData);
                sessionPromiseRef.current?.then(session => {
                  session.sendRealtimeInput({
                    media: {
                      mimeType: 'audio/pcm;rate=16000', // Explicitly 16kHz
                      data: pcmBase64
                    }
                  });
                });
              };

              sourceNodeRef.current.connect(processorRef.current);
              processorRef.current.connect(inputCtx.destination);

              if (contextCompany) {
                 const initialContext = `User is analyzing: ${contextCompany.name} (${contextCompany.industry}). 
                 Description: ${contextCompany.description.substring(0, 200)}...
                 Key Needs: ${contextCompany.needs.join(', ')}.
                 Open Roles: ${contextCompany.openRoles ? company.openRoles.map(r => r.title).join(', ') : 'None detected'}`;

                 sessionPromiseRef.current?.then(session => {
                     session.sendRealtimeInput({ text: initialContext });
                 });
              }
            },
            onmessage: async (msg: LiveServerMessage) => {
              if (!mounted) return;

              // Handle Interruption
              if (msg.serverContent?.interrupted) {
                  console.log("Recon Live: Interrupted");
                  stopAllAudio();
                  setStatus('listening');
                  return;
              }

              // Handle Audio Output
              const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
              if (audioData && outputContextRef.current) {
                setStatus('speaking');
                const buffer = await decodeAudioData(audioData, outputContextRef.current);

                const src = outputContextRef.current.createBufferSource();
                src.buffer = buffer;
                src.connect(outputContextRef.current.destination);

                // Track source for cancellation
                audioSourcesRef.current.push(src);
                src.onended = () => {
                    audioSourcesRef.current = audioSourcesRef.current.filter(s => s !== src);
                    if (audioSourcesRef.current.length === 0 && mounted) {
                        setStatus('listening');
                    }
                };

                const currentTime = outputContextRef.current.currentTime;
                const startTime = Math.max(currentTime, nextStartTimeRef.current);
                src.start(startTime);
                nextStartTimeRef.current = startTime + buffer.duration;
              }
            },
            onclose: () => {
              console.log("Recon Live: Closed");
              if (mounted) onClose();
            },
            onerror: (err) => {
              console.error("Recon Live Error:", err);
              if (mounted) setStatus('error');
            }
          }
        });

      } catch (err) {
        console.error("Setup Error", err);
        setStatus('error');
      }
    };

    if (isActive) {
      startSession();
    }

    return () => {
      mounted = false;
      stopAllAudio();

      // Cleanup Input
      if (mediaStreamRef.current) {
        mediaStreamRef.current.getTracks().forEach(t => t.stop());
      }
      if (processorRef.current && sourceNodeRef.current) {
        processorRef.current.disconnect();
        sourceNodeRef.current.disconnect();
      }
      if (inputContextRef.current) {
        inputContextRef.current.close();
        inputContextRef.current = null;
      }
      // Cleanup Output
      if (outputContextRef.current) {
        outputContextRef.current.close();
        outputContextRef.current = null;
      }
      sessionPromiseRef.current = null;
    };
  }, [isActive]);

  // Handle Context Updates
  useEffect(() => {
    if (isActive && contextCompany && contextCompany.id !== currentCompanyIdRef.current && sessionPromiseRef.current) {
        currentCompanyIdRef.current = contextCompany.id;
        const updateMsg = `Context Update: User switched to ${contextCompany.name}. Focus on this company now.`;
        sessionPromiseRef.current.then(session => {
            session.sendRealtimeInput({ text: updateMsg });
        });
    }
  }, [contextCompany, isActive]);

  if (!isActive) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in">
      <div className="relative w-full max-w-sm mx-auto p-6">

        {/* Main Card */}
        <div className="relative bg-neutral-900 border border-neutral-700 rounded-3xl shadow-2xl overflow-hidden flex flex-col items-center py-10 transition-all duration-300">

            {/* Close Button */}
            <button 
                onClick={onClose}
                className="absolute top-4 right-4 p-2 rounded-full bg-neutral-800 text-neutral-400 hover:text-white transition-colors hover:rotate-90 duration-300"
            >
                <X className="w-5 h-5" />
            </button>

            {/* Connection Status Indicator */}
            <div className="absolute top-5 left-6 flex items-center gap-2">
                 <div className={`w-2 h-2 rounded-full ${status === 'error' ? 'bg-red-500' : (status === 'connecting' ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500')}`}></div>
                 <span className="text-[10px] font-mono text-neutral-500 uppercase">
                    {status === 'connecting' ? 'SYNCING' : 'LIVE'}
                 </span>
            </div>

            {/* Visualizer Orb */}
            <div className="relative w-40 h-40 mb-8 flex items-center justify-center">
                {/* Background Rotating Ring 1 */}
                <div 
                    className="absolute inset-0 rounded-full border-2 border-accent/20 border-t-accent/60 animate-[spin_3s_linear_infinite]"
                    style={{ transform: `scale(${1 + volumeLevel * 0.5})` }}
                ></div>

                {/* Background Rotating Ring 2 (Counter-rotate) */}
                <div 
                    className="absolute inset-4 rounded-full border-2 border-purple-500/20 border-b-purple-500/60 animate-[spin_4s_linear_infinite_reverse]"
                    style={{ transform: `scale(${1 + volumeLevel * 0.3})` }}
                ></div>

                {/* Core Glow */}
                <div 
                    className={`absolute inset-0 rounded-full bg-accent/20 blur-2xl transition-all duration-100 ease-linear`}
                    style={{ transform: `scale(${1 + volumeLevel * 1.5})`, opacity: volumeLevel + 0.5 }}
                ></div>

                {/* Center Core */}
                <div 
                    className={`relative w-24 h-24 rounded-full flex items-center justify-center border transition-all duration-300 shadow-lg z-10
                    ${status === 'error' ? 'border-red-500 bg-red-900/50 shadow-red-500/50' : 
                      status === 'speaking' ? 'border-accent bg-accent text-white shadow-accent/50 scale-110' : 
                      'border-neutral-700 bg-neutral-800 text-neutral-400'}`}
                >
                    {status === 'connecting' && <Activity className="w-8 h-8 animate-pulse" />}
                    {status === 'listening' && <div className={`w-3 h-3 rounded-full bg-red-500 animate-pulse transition-all ${volumeLevel > 0.1 ? 'scale-150' : ''}`} />}
                    {status === 'speaking' && <Volume2 className="w-8 h-8 animate-bounce" />}
                    {status === 'error' && <X className="w-8 h-8" />}
                </div>
            </div>

            {/* Status Text */}
            <h3 className="text-xl font-bold text-white mb-2 tracking-wide uppercase">
                {status === 'connecting' && "Connecting..."}
                {status === 'listening' && "Listening"}
                {status === 'speaking' && "Recon AI"}
                {status === 'error' && "Connection Error"}
            </h3>

            <p className="text-xs font-mono text-neutral-500 text-center max-w-[240px] leading-relaxed">
                {status === 'error' ? "Microphone access denied or connection dropped." : 
                 contextCompany ? `Analyzing ${contextCompany.name}. Ask for open roles or contact info.` : "I'm listening. Ask me to find jobs, leads, or analyze companies."}
            </p>

            {/* Dynamic Waveform */}
            {status !== 'error' && (
                <div className="flex gap-1.5 mt-8 h-12 items-center justify-center">
                   {[...Array(7)].map((_, i) => (
                       <div 
                         key={i} 
                         className={`w-1.5 rounded-full transition-all duration-150 ease-in-out ${status === 'speaking' ? 'bg-accent' : 'bg-neutral-700'}`}
                         style={{ 
                             height: status === 'speaking' || (status === 'listening' && volumeLevel > 0.05) 
                               ? `${Math.random() * 40 + 10}px` 
                               : '4px',
                             opacity: status === 'speaking' ? 0.8 : 0.5
                         }}
                       ></div>
                   ))}
                </div>
            )}

            {/* Tool Indicators (Static for now, but implies capability) */}
            <div className="absolute bottom-4 flex gap-3 text-neutral-600">
               <Globe className="w-4 h-4 opacity-50" />
               <Wifi className="w-4 h-4 opacity-50" />
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Target, Send, Loader2, Sparkles, Copy, Check, Bot, Phone, Mail, Award, Globe, Linkedin, Twitter, Facebook, Instagram, Youtube, Link as LinkIcon, Zap, TrendingUp, DollarSign, Newspaper, Edit3, Bookmark, ShieldCheck, MapPin, Briefcase, UserPlus, Search, FileText, UserSearch, Briefcase as BriefcaseIcon, PlusCircle, CheckCircle, ExternalLink } from 'lucide-react';
import { Company, Pitch, Job, SavedJob } from '../types';
import { generatePitch } from '../services/geminiService';

interface IntelligencePaneProps {
  company: Company | null;
  onToggleSave: () => void;
  isSaved: boolean;
  onTrackJob: (job: Job) => void;
  savedJobs: SavedJob[];
}

type Tab = 'overview' | 'insights' | 'jobs' | 'outreach';
type PitchFormat = 'email' | 'linkedin_connect' | 'linkedin_inmail';

export const IntelligencePane: React.FC<IntelligencePaneProps> = ({ 
    company, 
    onToggleSave, 
    isSaved,
    onTrackJob,
    savedJobs 
}) => {
  const [activeTab, setActiveTab] = useState<Tab>('overview');
  const [skills, setSkills] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedPitches, setGeneratedPitches] = useState<Pitch[]>([]);
  const [activePitchIndex, setActivePitchIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [pitchFormat, setPitchFormat] = useState<PitchFormat>('email');

  // Outreach Context State
  const [outreachContext, setOutreachContext] = useState<'sales' | 'job_application'>('sales');
  const [targetJobTitle, setTargetJobTitle] = useState('');

  React.useEffect(() => {
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
    setActiveTab('overview');
    // Default to 'jobs' tab if company has open roles and we are in that mindset? No, Overview is safer.
  }, [company?.id]);

  const handleFormatChange = (format: PitchFormat) => {
    setPitchFormat(format);
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
  };

  const handleGenerate = async () => {
    if (!company || !skills) return;

    setIsGenerating(true);
    setGeneratedPitches([]);
    setActivePitchIndex(0);

    try {
      const signalContext = company.signals.map(s => `${s.type}: ${s.text}`);

      const results = await generatePitch({
        companyName: company.name,
        industry: company.industry,
        userSkills: skills,
        tone: 'Professional',
        companySignals: signalContext,
        format: pitchFormat,
        context: outreachContext,
        jobTitle: targetJobTitle
      });
      setGeneratedPitches(results);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const getSignalIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('fund') || t.includes('money')) return <DollarSign className="w-3 h-3 text-emerald-500" />;
    if (t.includes('hir') || t.includes('team') || t.includes('growth')) return <TrendingUp className="w-3 h-3 text-blue-500" />;
    if (t.includes('news') || t.includes('press')) return <Newspaper className="w-3 h-3 text-purple-500" />;
    if (t.includes('loc') || t.includes('hq')) return <MapPin className="w-3 h-3 text-orange-500" />;
    return <ShieldCheck className="w-3 h-3 text-accent" />;
  };

  const getSocialLinks = () => {
    if (!company || !company.socials || company.socials === 'N/A' || company.socials === 'None') return [];

    return company.socials
      .split(/[\s,\n]+/)
      .map(s => s.trim())
      .filter(s => s.length > 0 && !s.toLowerCase().includes('n/a'))
      .map((rawLink, index) => {
        let url = rawLink.replace(/[\[\]()]/g, '');
        if (!url.startsWith('http')) url = `https://${url}`;
        if (!url.includes('.') || url.length < 8) return null;

        let icon = <LinkIcon className="w-4 h-4" />;
        const lowerUrl = url.toLowerCase();

        if (lowerUrl.includes('linkedin')) icon = <Linkedin className="w-4 h-4" />;
        else if (lowerUrl.includes('twitter') || lowerUrl.includes('x.com')) icon = <Twitter className="w-4 h-4" />;
        else if (lowerUrl.includes('facebook')) icon = <Facebook className="w-4 h-4" />;
        else if (lowerUrl.includes('instagram')) icon = <Instagram className="w-4 h-4" />;
        else if (lowerUrl.includes('youtube')) icon = <Youtube className="w-4 h-4" />;

        return { url, icon, key: index };
      })
      .filter((link): link is { url: string; icon: React.ReactElement; key: number } => link !== null);
  };

  if (!company) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-neutral-400 select-none bg-neutral-50/50 dark:bg-black/20">
         <div className="max-w-md p-8">
            <div className="flex items-center gap-3 mb-6">
                <div className="p-3 bg-accent/10 rounded-xl">
                    <Target className="w-8 h-8 text-accent" />
                </div>
                <div>
                    <h2 className="text-xl font-bold text-neutral-900 dark:text-white">Welcome to Recon</h2>
                    <p className="text-sm text-neutral-500">Intelligence Suite for Lead Generation</p>
                </div>
            </div>

            <div className="space-y-4">
                <div className="flex items-start gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 shadow-sm">
                    <div className="mt-1 p-1.5 bg-blue-500/10 rounded-lg">
                        <Search className="w-4 h-4 text-blue-500" />
                    </div>
                    <div>
                        <h4 className="text-sm font-bold text-neutral-900 dark:text-white">1. Discover</h4>
                        <p className="text-xs text-neutral-500 mt-1">Search by Industry, City or Role (e.g., "Copywriter in Mumbai") to find leads.</p>
                    </div>
                </div>

                 <div className="flex items-start gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 shadow-sm">
                    <div className="mt-1 p-1.5 bg-purple-500/10 rounded-lg">
                        <FileText className="w-4 h-4 text-purple-500" />
                    </div>
                    <div>
                        <h4 className="text-sm font-bold text-neutral-900 dark:text-white">2. Analyze & Track Jobs</h4>
                        <p className="text-xs text-neutral-500 mt-1">View open roles, verified contact info, and track your application pipeline.</p>
                    </div>
                </div>

                 <div className="flex items-start gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 shadow-sm">
                    <div className="mt-1 p-1.5 bg-green-500/10 rounded-lg">
                        <Send className="w-4 h-4 text-green-500" />
                    </div>
                    <div>
                        <h4 className="text-sm font-bold text-neutral-900 dark:text-white">3. Outreach</h4>
                        <p className="text-xs text-neutral-500 mt-1">Generate AI-personalized emails or job applications tailored to the company.</p>
                    </div>
                </div>
            </div>
         </div>
      </div>
    );
  }

  const socialLinks = getSocialLinks();
  const currentPitch = generatedPitches[activePitchIndex];

  // Helper to check if a job is tracked
  const isJobTracked = (jobId: string) => savedJobs.some(j => j.id === jobId);

  return (
    <div className="h-full flex flex-col bg-white dark:bg-neutral-900 rounded-2xl border border-neutral-200 dark:border-white/10 shadow-glass overflow-hidden">

      {/* Header */}
      <div className="p-6 border-b border-neutral-200 dark:border-white/5 bg-neutral-50/50 dark:bg-black/20">
         <div className="flex justify-between items-start mb-4">
             <div>
                 <h2 className="text-xl font-bold text-neutral-900 dark:text-white tracking-tight">{company.name}</h2>
                 <div className="flex items-center gap-2 text-xs text-neutral-500 mt-1">
                     <Briefcase className="w-3 h-3" />
                     <span>{company.industry}</span>
                     <span className="text-neutral-300 dark:text-neutral-700">•</span>
                     <MapPin className="w-3 h-3" />
                     <span>{company.location || "Unknown Location"}</span>
                 </div>
             </div>

             <button 
                onClick={onToggleSave}
                className={`p-2 rounded-lg border transition-all ${isSaved ? 'bg-accent/10 border-accent text-accent' : 'bg-white dark:bg-neutral-800 border-neutral-200 dark:border-white/10 text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                title={isSaved ? "Remove Company" : "Save Company"}
             >
                 <Bookmark className={`w-4 h-4 ${isSaved ? 'fill-accent' : ''}`} />
             </button>
         </div>

         {/* Stats Bar */}
         <div className="flex items-center gap-4">
             <div className="px-3 py-1.5 rounded-md bg-neutral-100 dark:bg-white/5 border border-neutral-200 dark:border-white/5 flex items-center gap-2">
                 <Zap className="w-3 h-3 text-amber-500" />
                 <span className="text-xs font-bold text-neutral-700 dark:text-neutral-300">Match: {company.hotScore}%</span>
             </div>
             <div className="flex gap-2">
                 {socialLinks.map(link => (
                     <a key={link.key} href={link.url} target="_blank" rel="noreferrer" className="p-1.5 rounded-md hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-400 hover:text-accent transition-colors">
                        {link.icon}
                     </a>
                 ))}
                 {company.website !== 'N/A' && (
                     <a href={company.website.startsWith('http') ? company.website : `https://${company.website}`} target="_blank" rel="noreferrer" className="p-1.5 rounded-md hover:bg-neutral-200 dark:hover:bg-white/10 text-neutral-400 hover:text-accent transition-colors">
                        <Globe className="w-4 h-4" />
                     </a>
                 )}
             </div>
         </div>
      </div>

      {/* Navigation Tabs */}
      <div className="flex border-b border-neutral-200 dark:border-white/5">
          {['overview', 'insights', 'jobs', 'outreach'].map((tab) => (
             <button 
                key={tab}
                onClick={() => setActiveTab(tab as Tab)} 
                className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider transition-all border-b-2 
                    ${activeTab === tab 
                        ? 'border-accent text-accent bg-accent/5' 
                        : 'border-transparent text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
             >
                {tab}
             </button>
          ))}
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto p-6 bg-neutral-50/30 dark:bg-neutral-900/30">

        {/* TAB: OVERVIEW */}
        {activeTab === 'overview' && (
            <div className="space-y-6 animate-fade-in">
                <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                    <h3 className="text-xs font-bold text-neutral-500 uppercase mb-3">Company Overview</h3>
                    <p className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed">
                        {company.description}
                    </p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                        <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <Award className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Hero Product</span>
                        </div>
                        <p className="text-sm font-medium text-neutral-900 dark:text-white">{company.heroProduct}</p>
                    </div>
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                         <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <Target className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Identified Needs</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {company.needs.map((need, i) => (
                                <span key={i} className="px-2 py-1 rounded text-[10px] font-bold bg-neutral-100 dark:bg-white/10 text-neutral-600 dark:text-neutral-300">
                                    {need}
                                </span>
                            ))}
                        </div>
                    </div>
                </div>

                {company.hiringCulture && (
                    <div className="bg-white dark:bg-neutral-800/50 p-4 rounded-xl border border-neutral-200 dark:border-white/5">
                        <div className="flex items-center gap-2 mb-2 text-neutral-500">
                            <UserSearch className="w-3 h-3" />
                            <span className="text-xs font-bold uppercase">Hiring Culture</span>
                        </div>
                        <p className="text-sm text-neutral-700 dark:text-neutral-300 leading-relaxed">
                            {company.hiringCulture}
                        </p>
                    </div>
                )}
            </div>
        )}

        {/* TAB: INSIGHTS (EVIDENCE) */}
        {activeTab === 'insights' && (
             <div className="space-y-4 animate-fade-in">
                {company.signals.length === 0 ? (
                    <div className="text-center py-10 text-neutral-500">
                        <p className="text-sm">No specific insights detected.</p>
                    </div>
                ) : (
                    company.signals.map((signal, idx) => (
                        <div key={idx} className="flex gap-4 p-4 bg-white dark:bg-neutral-800/50 rounded-xl border border-neutral-200 dark:border-white/5 items-start">
                             <div className="mt-1 p-2 rounded-lg bg-neutral-50 dark:bg-white/5">
                                 {getSignalIcon(signal.type)}
                             </div>
                             <div>
                                 <div className="flex items-center gap-2 mb-1">
                                     <span className="text-xs font-bold uppercase text-neutral-900 dark:text-white">{signal.type}</span>
                                     <span className={`text-[9px] px-1.5 py-0.5 rounded ${signal.confidence === 'High' ? 'bg-green-500/10 text-green-500' : 'bg-neutral-500/10 text-neutral-500'}`}>
                                         {signal.confidence} Confidence
                                     </span>
                                 </div>
                                 <p className="text-sm text-neutral-600 dark:text-neutral-400 leading-snug">{signal.text}</p>
                             </div>
                        </div>
                    ))
                )}
                 <div className="p-4 rounded-xl bg-amber-50/50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-500/20 text-xs text-amber-800 dark:text-amber-500 leading-relaxed">
                    <strong className="block mb-1">AI Analysis:</strong>
                    {company.scoreReasoning || "Automated assessment based on visible digital footprint and relevance."}
                 </div>
             </div>
        )}

        {/* TAB: JOBS */}
        {activeTab === 'jobs' && (
            <div className="space-y-4 animate-fade-in">
                {(!company.openRoles || company.openRoles.length === 0) ? (
                    <div className="text-center py-12 text-neutral-500 flex flex-col items-center">
                        <BriefcaseIcon className="w-10 h-10 mb-3 opacity-30" />
                        <p className="text-sm font-medium">No open roles detected.</p>
                        <p className="text-xs opacity-70 mt-1">Try checking their Careers page directly.</p>
                    </div>
                ) : (
                    <div className="grid gap-3">
                        {company.openRoles.map((role, idx) => {
                           const tracked = isJobTracked(role.id);
                           return (
                            <div key={idx} className="bg-white dark:bg-neutral-800 p-4 rounded-xl border border-neutral-200 dark:border-white/5 hover:border-accent/30 transition-all shadow-sm">
                                <div className="flex justify-between items-start">
                                    <div>
                                        <h4 className="font-bold text-neutral-900 dark:text-white text-sm">{role.title}</h4>
                                        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-neutral-500 mt-1.5">
                                            <span className="flex items-center gap-1"><MapPin className="w-3 h-3"/> {role.location}</span>
                                            {role.type && <span className="bg-neutral-100 dark:bg-white/5 px-1.5 py-0.5 rounded">{role.type}</span>}
                                            {role.salary && <span className="text-emerald-600 dark:text-emerald-400 font-medium">{role.salary}</span>}
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        <button 
                                            onClick={() => {
                                                setOutreachContext('job_application');
                                                setTargetJobTitle(role.title);
                                                setActiveTab('outreach');
                                            }}
                                            className="p-2 text-neutral-400 hover:text-accent hover:bg-accent/10 rounded-lg transition-colors"
                                            title="Draft Application"
                                        >
                                            <Send className="w-4 h-4" />
                                        </button>
                                        <button 
                                            onClick={() => onTrackJob(role)}
                                            className={`p-2 rounded-lg transition-colors border ${tracked ? 'bg-green-500/10 border-green-500 text-green-500' : 'bg-transparent border-neutral-200 dark:border-white/10 text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                                            title={tracked ? "Tracked" : "Track Role"}
                                        >
                                            {tracked ? <CheckCircle className="w-4 h-4" /> : <PlusCircle className="w-4 h-4" />}
                                        </button>
                                    </div>
                                </div>
                                {role.link && (
                                     <a href={role.link} target="_blank" rel="noreferrer" className="mt-3 text-xs text-accent hover:underline inline-flex items-center gap-1">
                                         View Full Listing <ExternalLink className="w-3 h-3" />
                                     </a>
                                )}
                            </div>
                           );
                        })}
                    </div>
                )}
            </div>
        )}

        {/* TAB: OUTREACH (COMMS) */}
        {activeTab === 'outreach' && (
            <div className="h-full flex flex-col animate-fade-in">

                {/* Context Switcher */}
                <div className="flex items-center justify-between mb-4">
                     <div className="flex p-1 bg-neutral-100 dark:bg-neutral-800/50 rounded-lg border border-neutral-200 dark:border-white/5">
                        <button
                            onClick={() => { setOutreachContext('sales'); setTargetJobTitle(''); }}
                            className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${outreachContext === 'sales' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white' : 'text-neutral-500'}`}
                        >
                            Sales Pitch
                        </button>
                        <button
                            onClick={() => { setOutreachContext('job_application'); }}
                            className={`px-3 py-1.5 text-xs font-bold rounded-md transition-all ${outreachContext === 'job_application' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white' : 'text-neutral-500'}`}
                        >
                            Job Application
                        </button>
                     </div>
                     {outreachContext === 'job_application' && (
                         <input 
                            type="text" 
                            value={targetJobTitle}
                            onChange={(e) => setTargetJobTitle(e.target.value)}
                            placeholder="Target Role..."
                            className="bg-transparent border-b border-neutral-200 dark:border-white/10 px-2 py-1 text-xs text-right focus:outline-none focus:border-accent w-32"
                         />
                     )}
                </div>

                <div className="flex flex-wrap items-center gap-2 mb-4">
                    <button 
                        onClick={() => handleFormatChange('email')}
                        className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 border border-transparent ${pitchFormat === 'email' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white border-neutral-200 dark:border-white/5' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                    >
                        <Mail className="w-3.5 h-3.5" />
                        Email
                    </button>
                    <button 
                        onClick={() => handleFormatChange('linkedin_inmail')}
                        className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 border border-transparent ${pitchFormat === 'linkedin_inmail' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white border-neutral-200 dark:border-white/5' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                    >
                        <Linkedin className="w-3.5 h-3.5" />
                        InMail
                    </button>
                    <button 
                        onClick={() => handleFormatChange('linkedin_connect')}
                        className={`px-3 py-1.5 rounded-md text-xs font-bold transition-all flex items-center gap-2 border border-transparent ${pitchFormat === 'linkedin_connect' ? 'bg-white dark:bg-neutral-700 shadow-sm text-neutral-900 dark:text-white border-neutral-200 dark:border-white/5' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                    >
                        <UserPlus className="w-3.5 h-3.5" />
                        Connect
                    </button>
                </div>

                <div className="mb-4">
                    <label className="text-xs font-bold text-neutral-500 uppercase mb-2 block">Your Offer / Skills</label>
                    <div className="flex gap-2">
                        <input 
                            type="text" 
                            value={skills}
                            onChange={(e) => setSkills(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleGenerate()}
                            placeholder={outreachContext === 'job_application' ? "e.g. 5 yrs Exp in React, UI Design" : "e.g. SEO services for e-commerce"} 
                            className="flex-1 bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-white/10 rounded-lg px-3 py-2 text-sm text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent"
                        />
                        <button 
                            onClick={handleGenerate}
                            disabled={!skills || isGenerating}
                            className={`px-4 rounded-lg bg-accent text-white hover:bg-accent-glow disabled:opacity-50 transition-colors shadow-sm`}
                        >
                            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Sparkles className="w-4 h-4" />}
                        </button>
                    </div>
                </div>

                {generatedPitches.length > 0 ? (
