    const y = e.clientY;
    document.documentElement.style.setProperty('--mouse-x', `${x}px`);
    document.documentElement.style.setProperty('--mouse-y', `${y}px`);
  }, []);

  // BACKGROUND TASK: Prefetch the next 5 leads
  const prefetchNextBatch = async (currentResults: Company[], params: SearchParams) => {
    if (params.mode === 'lookup') return; // Don't prefetch for single lookups

    setIsPrefetching(true);
    try {
        const excludeNames = [...currentResults.map(c => c.name), ...savedCompanies.map(c => c.name)];
        const nextParams = { ...params, excludeNames };

        const result = await findLeads(nextParams, abortControllerRef.current?.signal);
        setNextBatch(result);
    } catch (error: any) {
        if (error.name !== 'AbortError') {
            console.log("Prefetch suspended or failed (non-critical).");
        }
    } finally {
        setIsPrefetching(false);
    }
  };

  const handleSearch = async (mode: SearchMode, p1: string, p2: string) => {
    // 1. STOP EVERYTHING
    if (abortControllerRef.current) {
        abortControllerRef.current.abort();
    }
    abortControllerRef.current = new AbortController();

    setIsSearching(true);
    setSearchResults([]); 
    setSearchSources([]);
    setNextBatch(null); 
    setSelectedCompanyId(null);

    // MAPPING ARGS TO PARAMS
    // Discovery: p1=Industry, p2=City
    // Jobs: p1=Role, p2=City
    // Lookup: p1=CompanyName, p2=City

    const params: SearchParams = {
        mode,
        industry: mode === 'discovery' ? p1 : undefined,
        city: p2,
        role: mode === 'jobs' ? p1 : undefined,
        companyName: mode === 'lookup' ? p1 : undefined,
        excludeNames: savedCompanies.map(c => c.name)
    };
    currentSearchParamsRef.current = params;

    try {
      const { leads, sources } = await findLeads(params, abortControllerRef.current.signal);
      setSearchResults(leads);
      setSearchSources(sources);

      if (leads.length === 0) {
        addToast("No leads found. Try a broader search.", "info");
      } else {
        prefetchNextBatch(leads, params);
      }
    } catch (error: any) {
      if (error.name === 'AbortError') {
          console.log("Search aborted by user.");
      } else {
          console.error("Search failed", error);
          addToast(error.message || "Could not find leads.", "error");
      }
    } finally {
      if (!abortControllerRef.current?.signal.aborted) {
          setIsSearching(false);
      }
    }
  };

  const handleLoadMore = async () => {
    if (!currentSearchParamsRef.current || currentSearchParamsRef.current.mode === 'lookup') return;

    // STRATEGY: Instant Load if buffer is ready
    if (nextBatch && nextBatch.leads.length > 0) {
        const batchLeads = nextBatch.leads;
        const batchSources = nextBatch.sources;

        setNextBatch(null); // Clear buffer immediately

        setSearchResults(prev => {
            const updated = [...prev, ...batchLeads];
            prefetchNextBatch(updated, currentSearchParamsRef.current!); 
            return updated;
        });
        setSearchSources(prev => {
            // Merge and dedupe sources
            const combined = [...prev, ...batchSources];
            return combined.filter((v, i, a) => a.findIndex(t => (t.uri === v.uri)) === i);
        });
        return;
    }

    // Fallback
    setIsSearching(true);
    try {
      const excludeNames = [...searchResults.map(c => c.name), ...savedCompanies.map(c => c.name)];
      const params: SearchParams = { ...currentSearchParamsRef.current, excludeNames };

      const { leads, sources } = await findLeads(params, abortControllerRef.current?.signal);

      if (leads.length === 0) {
        addToast("No more unique leads found in this area.", "info");
      } else {
        setSearchResults(prev => {
            const updated = [...prev, ...leads];
            prefetchNextBatch(updated, currentSearchParamsRef.current!);
            return updated;
        });
        setSearchSources(prev => {
             const combined = [...prev, ...sources];
             return combined.filter((v, i, a) => a.findIndex(t => (t.uri === v.uri)) === i);
        });
      }
    } catch (error: any) {
       if (error.name !== 'AbortError') {
          addToast(error.message || "Failed to load more leads.", "error");
       }
    } finally {
      setIsSearching(false);
    }
  };

  const toggleSaveCompany = (company: Company) => {
    if (savedCompanies.some(c => c.id === company.id)) {
        // Remove
        setSavedCompanies(prev => prev.filter(c => c.id !== company.id));
        addToast("Company removed from saved list", "info");
    } else {
        // Add
        const newCompany = { ...company, status: 'Saved' as const };
        setSavedCompanies(prev => [newCompany, ...prev]);
        addToast("Company saved successfully", "success");
    }
  };

  const trackJob = (job: Job, company: Company) => {
      const existing = savedJobs.find(j => j.id === job.id);
      if (existing) {
          addToast("Job already tracked.", "info");
          return;
      }
      const newJob: SavedJob = {
          ...job,
          companyId: company.id,
          companyName: company.name,
          status: 'Saved'
      };
      setSavedJobs(prev => [newJob, ...prev]);

      // Auto-save company if not saved? Let's leave them separate but user likely wants company saved too.
      // Optionally toggleSaveCompany(company) if not present.
      if (!savedCompanies.some(c => c.id === company.id)) {
          toggleSaveCompany(company);
      }

      addToast("Job added to pipeline.", "success");
  };

  const updateJobStatus = (jobId: string, status: 'Saved' | 'Applied' | 'Interviewing' | 'Offer') => {
      setSavedJobs(prev => prev.map(j => j.id === jobId ? { ...j, status } : j));
  };

  const removeJobs = (jobIds: string[]) => {
      setSavedJobs(prev => prev.filter(j => !jobIds.includes(j.id)));
      addToast("Jobs removed from pipeline.", "info");
  };

  const removeMultipleSavedCompanies = (ids: string[]) => {
    setSavedCompanies(prev => prev.filter(c => !ids.includes(c.id)));
    if (selectedCompanyId && ids.includes(selectedCompanyId)) {
        setSelectedCompanyId(null);
    }
    addToast(`Deleted ${ids.length} companies`, "info");
  };

  const selectedCompany = 
    searchResults.find(c => c.id === selectedCompanyId) || 
    savedCompanies.find(c => c.id === selectedCompanyId) || 
    null;

  return (
    <div 
      onMouseMove={handleMouseMove}
      className="h-screen bg-neutral-50 dark:bg-neutral-950 transition-colors duration-400 overflow-hidden flex flex-col relative"
    >
      {/* Voice Mode Overlay */}
      <VoiceMode 
        isActive={isVoiceModeActive} 
        onClose={() => setIsVoiceModeActive(false)} 
        contextCompany={selectedCompany} 
      />

      {/* Floating Action Button for Voice - High Z-Index to Ensure Visibility */}
      <div className="fixed bottom-6 right-6 z-[100] flex flex-col items-end space-y-4 pointer-events-none">
         {/* Toast Area */}
         <div className="flex flex-col gap-2 pointer-events-auto items-end">
            {toasts.map(toast => (
                <Toast key={toast.id} {...toast} onClose={() => removeToast(toast.id)} />
            ))}
         </div>

         {/* FAB */}
         <button
            onClick={() => setIsVoiceModeActive(true)}
            aria-label="Start Voice Assistant"
            className="pointer-events-auto group relative flex items-center justify-center w-14 h-14 rounded-full bg-gradient-to-tr from-accent to-accent-glow text-white shadow-lg shadow-accent/40 hover:scale-110 hover:shadow-accent/60 transition-all duration-300 ease-out focus:outline-none focus:ring-4 focus:ring-accent/30"
         >
            <div className="absolute inset-0 rounded-full bg-white opacity-0 group-hover:opacity-20 animate-ping duration-1000"></div>
            <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-accent to-accent-glow opacity-80 blur-md"></div>
            <Mic className="w-6 h-6 relative z-10 drop-shadow-sm" />
         </button>
      </div>

      <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
        <div className={`absolute -top-[20%] -left-[10%] w-[50%] h-[50%] rounded-full blur-[120px] transition-opacity duration-1000 ${isDarkMode ? 'bg-accent/5' : 'bg-accent/10'}`}></div>
        <div className="absolute inset-0 spotlight-bg opacity-100 transition-opacity duration-500"></div>
      </div>

      <div className="relative z-10 flex flex-col h-full">
        <Header 
            isDarkMode={isDarkMode} 
            toggleTheme={toggleTheme} 
            onVoiceToggle={() => setIsVoiceModeActive(true)}
        />

        <main className="flex-1 w-full max-w-screen-2xl mx-auto flex overflow-hidden">

          <div className="hidden lg:block w-72 h-full shrink-0">
             <Sidebar 
                savedCompanies={savedCompanies}
                savedJobs={savedJobs}
                onSelectCompany={(c) => setSelectedCompanyId(c.id)}
                selectedCompanyId={selectedCompanyId}
                onRemoveCompanies={removeMultipleSavedCompanies}
                onUpdateJobStatus={updateJobStatus}
                onRemoveJobs={removeJobs}
             />
          </div>

           {showMobileSidebar && (
              <div className="fixed inset-0 z-50 lg:hidden flex">
                  <div className="w-72 h-full bg-neutral-900 shadow-2xl animate-fade-in">
                     <Sidebar 
                        savedCompanies={savedCompanies}
                        savedJobs={savedJobs}
                        onSelectCompany={(c) => { setSelectedCompanyId(c.id); setShowMobileSidebar(false); }}
                        selectedCompanyId={selectedCompanyId}
                        onRemoveCompanies={removeMultipleSavedCompanies}
                        onUpdateJobStatus={updateJobStatus}
                        onRemoveJobs={removeJobs}
                     />
                  </div>
                  <div 
                    className="flex-1 bg-black/50 backdrop-blur-sm" 
                    onClick={() => setShowMobileSidebar(false)}
                    aria-label="Close Sidebar"
                  ></div>
              </div>
           )}

          <div className="flex-1 flex flex-col lg:flex-row min-w-0">

            <div className="lg:hidden p-2 border-b border-neutral-200 dark:border-white/10 flex items-center justify-between bg-neutral-100/50 dark:bg-neutral-900/50">
               <button 
                onClick={() => setShowMobileSidebar(true)} 
                aria-label="Open Saved List"
                className="flex items-center gap-2 text-xs font-bold uppercase text-neutral-500"
               >
                  <Menu className="w-4 h-4" /> Open Saved List
               </button>
               <span className="text-[10px] text-accent font-mono">{savedCompanies.length} SAVED</span>
            </div>

            <div className={`
                flex-1 flex flex-col h-full min-w-0 border-r border-neutral-200 dark:border-white/5 bg-white/30 dark:bg-neutral-950/30
                ${selectedCompanyId ? 'hidden lg:flex' : 'flex'} 
            `}>
              <div className="p-4 h-full">
                <SearchPane 
                    companies={searchResults} 
                    sources={searchSources}
                    selectedCompanyId={selectedCompanyId}
                    onSelectCompany={setSelectedCompanyId}
                    onSearch={handleSearch}
                    onLoadMore={handleLoadMore}
                    isSearching={isSearching}
                />
              </div>
            </div>

            <div className={`
                lg:w-[600px] xl:w-[700px] h-full flex-col bg-white/50 dark:bg-neutral-900/50 backdrop-blur-md
                ${selectedCompanyId ? 'flex fixed inset-0 z-40 lg:static lg:z-auto' : 'hidden lg:flex'}
            `}>
               {selectedCompanyId && (
                  <div className="lg:hidden p-4 border-b border-neutral-200 dark:border-white/10 flex items-center justify-between bg-white dark:bg-neutral-900">
                      <button 
                          onClick={() => setSelectedCompanyId(null)}
                          className="text-sm font-medium text-neutral-500 flex items-center gap-2"
                      >
                          <ChevronRight className="w-4 h-4 rotate-180" /> Back
                      </button>
                  </div>
               )}

               <div className="flex-1 h-full overflow-hidden p-4">
                  <IntelligencePane 
                      company={selectedCompany} 
                      onToggleSave={() => selectedCompany && toggleSaveCompany(selectedCompany)}
                      isSaved={!!selectedCompany && savedCompanies.some(c => c.id === selectedCompany.id)}
                      onTrackJob={(job) => selectedCompany && trackJob(job, selectedCompany)}
                      savedJobs={savedJobs}
                  />
               </div>
            </div>

          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Search, MapPin, Briefcase, ChevronRight, Globe, Loader2, Radar, Building2, Flame, ExternalLink, RefreshCw, UserSearch } from 'lucide-react';
import { Company, SearchMode, Source } from '../types';

interface SearchPaneProps {
  companies: Company[];
  sources?: Source[];
  selectedCompanyId: string | null;
  onSelectCompany: (id: string) => void;
  onSearch?: (mode: SearchMode, p1: string, p2: string) => void;
  onLoadMore?: () => void;
  isSearching?: boolean;
}

const SkeletonCard = () => (
  <div className="p-4 rounded-xl border border-neutral-200 dark:border-white/5 bg-white dark:bg-neutral-900/50 space-y-3 animate-pulse">
    <div className="flex justify-between items-start">
        <div className="space-y-2 w-full">
             <div className="h-4 bg-neutral-200 dark:bg-neutral-800 rounded w-1/3"></div>
             <div className="h-3 bg-neutral-200 dark:bg-neutral-800 rounded w-1/2"></div>
        </div>
        <div className="w-10 h-5 bg-neutral-200 dark:bg-neutral-800 rounded"></div>
    </div>
    <div className="h-2 bg-neutral-200 dark:bg-neutral-800 rounded w-full"></div>
    <div className="h-2 bg-neutral-200 dark:bg-neutral-800 rounded w-2/3"></div>
  </div>
);

export const SearchPane: React.FC<SearchPaneProps> = ({ 
  companies,
  sources = [],
  selectedCompanyId, 
  onSelectCompany,
  onSearch,
  onLoadMore,
  isSearching = false
}) => {
  const [mode, setMode] = useState<SearchMode>('discovery');

  // Discovery Inputs
  const [industry, setIndustry] = useState('');
  const [city, setCity] = useState('');

  // Lookup Inputs
  const [companyName, setCompanyName] = useState('');
  const [lookupCity, setLookupCity] = useState('');

  // Jobs Inputs
  const [role, setRole] = useState('');
  const [jobCity, setJobCity] = useState('');

  // Loading Message State
  const [loadingText, setLoadingText] = useState('Searching...');

  // Infinite Scroll Ref
  const loadMoreRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isSearching) return;

    const messages = mode === 'jobs' ? [
        "Scanning Job Boards...",
        "Identifying Companies...",
        "Checking Career Pages...",
        "Evaluating Hiring Culture...",
        "Compiling Open Roles..."
    ] : [
        "Analyzing Industry...",
        "Finding Companies...",
        "Finding Contact Info...",
        "Verifying Details...",
        "Preparing Report..."
    ];

    let i = 0;
    const interval = setInterval(() => {
        setLoadingText(messages[i]);
        i = (i + 1) % messages.length;
    }, 1200);

    return () => clearInterval(interval);
  }, [isSearching, mode]);

  // Infinite Scroll Observer
  useEffect(() => {
    if (!onLoadMore || mode === 'lookup' || isSearching || companies.length === 0) return;

    const observer = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) {
        onLoadMore();
      }
    }, { threshold: 0.1 });

    if (loadMoreRef.current) {
      observer.observe(loadMoreRef.current);
    }

    return () => observer.disconnect();
  }, [companies.length, isSearching, mode, onLoadMore]);

  const handleSubmit = () => {
    if (!onSearch) return;

    if (mode === 'discovery') {
       if (industry && city) onSearch('discovery', industry, city);
    } else if (mode === 'jobs') {
       if (role && jobCity) onSearch('jobs', role, jobCity);
    } else {
       if (companyName) onSearch('lookup', companyName, lookupCity || 'Anywhere'); 
    }
  };

  const getHotScoreColor = (score: number) => {
    if (score >= 80) return 'from-red-500 to-orange-500';
    if (score >= 60) return 'from-orange-400 to-amber-400';
    return 'from-neutral-400 to-neutral-500';
  };

  return (
    <div className="flex flex-col h-full">

      {/* Search Header Area - Fixed Top */}
      <div className="mb-2 space-y-4 relative z-10 bg-neutral-50 dark:bg-neutral-950 pb-2">
        <div className="flex items-center justify-between px-1">
             <h2 className="text-lg font-semibold text-neutral-900 dark:text-white tracking-tight">
               Search
             </h2>
             {/* Mode Toggles */}
             <div className="flex p-1 rounded-lg bg-neutral-200 dark:bg-white/5 border border-neutral-200 dark:border-white/5" role="tablist">
                 <button
                    onClick={() => setMode('discovery')}
                    role="tab"
                    aria-selected={mode === 'discovery'}
                    className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all ${mode === 'discovery' ? 'bg-white dark:bg-neutral-800 text-accent shadow-sm' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                 >
                    Leads
                 </button>
                 <button
                    onClick={() => setMode('jobs')}
                    role="tab"
                    aria-selected={mode === 'jobs'}
                    className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all ${mode === 'jobs' ? 'bg-white dark:bg-neutral-800 text-accent shadow-sm' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                 >
                    Jobs
                 </button>
                 <button
                    onClick={() => setMode('lookup')}
                    role="tab"
                    aria-selected={mode === 'lookup'}
                    className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md transition-all ${mode === 'lookup' ? 'bg-white dark:bg-neutral-800 text-accent shadow-sm' : 'text-neutral-500 hover:text-neutral-900 dark:hover:text-white'}`}
                 >
                    Lookup
                 </button>
             </div>
        </div>

        <div className="space-y-3">
          {mode === 'discovery' && (
              <>
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Briefcase className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={industry}
                    onChange={(e) => setIndustry(e.target.value)}
                    placeholder="Industry (e.g. SaaS)"
                    aria-label="Industry"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>

                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <MapPin className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={city}
                    onChange={(e) => setCity(e.target.value)}
                    placeholder="City (e.g. London)"
                    aria-label="City"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>
              </>
          )}

          {mode === 'jobs' && (
              <>
                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <UserSearch className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={role}
                    onChange={(e) => setRole(e.target.value)}
                    placeholder="Role (e.g. Copywriter)"
                    aria-label="Role"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>

                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <MapPin className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={jobCity}
                    onChange={(e) => setJobCity(e.target.value)}
                    placeholder="City (e.g. Mumbai)"
                    aria-label="City"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>
              </>
          )}

          {mode === 'lookup' && (
              <>
                 <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Building2 className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={companyName}
                    onChange={(e) => setCompanyName(e.target.value)}
                    placeholder="Company Name"
                    aria-label="Company Name"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>

                <div className="relative group">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <MapPin className="h-4 w-4 text-neutral-400 group-focus-within:text-accent transition-colors duration-300" />
                    </div>
                    <input
                    type="text"
                    value={lookupCity}
                    onChange={(e) => setLookupCity(e.target.value)}
                    placeholder="City (Optional)"
                    aria-label="City"
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    className="block w-full pl-10 pr-3 py-3 rounded-xl border border-neutral-200 dark:border-white/10 bg-white dark:bg-neutral-900 text-neutral-900 dark:text-white placeholder-neutral-400 focus:outline-none focus:ring-2 focus:ring-accent focus:border-transparent transition-all shadow-sm hover:shadow-md dark:hover:bg-neutral-800"
                    />
                </div>
              </>
          )}

          <button 
            onClick={handleSubmit}
            disabled={
                isSearching || 
                (mode === 'discovery' ? (!industry || !city) : 
                 mode === 'jobs' ? (!role || !jobCity) : 
                 !companyName)
            }
            className={`
              w-full flex items-center justify-center py-3 px-4 rounded-xl font-medium transition-all duration-300 shadow-lg 
              ${isSearching || (mode === 'discovery' ? (!industry || !city) : mode === 'jobs' ? (!role || !jobCity) : !companyName)
                ? 'bg-neutral-200 dark:bg-neutral-800 text-neutral-400 cursor-not-allowed shadow-none' 
                : 'bg-accent hover:bg-accent-glow text-white shadow-accent/20 hover:shadow-accent/40 active:scale-[0.98]'}
            `}
          >
            {isSearching && companies.length === 0 ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Search className="w-4 h-4 mr-2" />}
            {isSearching && companies.length === 0 ? (
                <span className="font-mono text-xs uppercase tracking-wide animate-pulse">{loadingText}</span>
            ) : (
                mode === 'discovery' ? 'Find Leads' : mode === 'jobs' ? 'Find Jobs' : 'Lookup'
            )}
          </button>
        </div>
      </div>

      {/* Soft Gradient Divider */}
      <div className="h-6 w-full bg-gradient-to-b from-neutral-50 via-neutral-50 to-transparent dark:from-neutral-950 dark:via-neutral-950 z-10 shrink-0"></div>

      {/* Results List - SCROLLABLE AREA */}
      <div id="results-container" className="flex-1 overflow-y-auto -mx-2 px-2 pb-4 space-y-3 min-h-0 custom-scrollbar">
        {isSearching && companies.length === 0 ? (
             <div className="space-y-3">
                 <SkeletonCard />
                 <SkeletonCard />
                 <SkeletonCard />
                 <SkeletonCard />
             </div>
        ) : (
            <>
                {companies.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-60 animate-fade-in p-8">
                    <div className="w-16 h-16 rounded-full bg-neutral-100 dark:bg-neutral-900/50 flex items-center justify-center mb-4 ring-1 ring-neutral-200 dark:ring-white/5">
                        <Radar className="w-8 h-8 text-neutral-400" />
                    </div>
                    <h3 className="text-sm font-semibold text-neutral-900 dark:text-white mb-1">
                    Ready to Search
                    </h3>
                    <p className="text-xs text-neutral-500 max-w-[200px] leading-relaxed">
                        Enter your search criteria above to begin.
                    </p>
                </div>
                )}

                {companies.map((company, index) => {
                const isSelected = selectedCompanyId === company.id;
                const animationDelay = `${(index % 10) * 50}ms`;
                const hotColor = getHotScoreColor(company.hotScore);
                const openRolesCount = company.openRoles?.length || 0;

                return (
                    <div
                    key={company.id}
                    onClick={() => onSelectCompany(company.id)}
                    style={{ animationDelay }}
                    className={`
                        relative p-4 rounded-xl border cursor-pointer transition-all duration-300 group opacity-0 animate-fade-in-up
                        ${isSelected 
                        ? 'bg-white dark:bg-neutral-800 border-accent shadow-md ring-1 ring-accent z-10 scale-[1.01]' 
                        : 'bg-white dark:bg-neutral-900/50 border-neutral-200 dark:border-white/5 hover:border-neutral-300 dark:hover:border-white/20 hover:shadow-sm hover:bg-white dark:hover:bg-neutral-800/80'}
                    `}
                    >
                    <div className="flex justify-between items-start">
                        <div className="flex-1 mr-2">
                        <h3 className={`font-semibold text-sm transition-colors ${isSelected ? 'text-neutral-900 dark:text-white' : 'text-neutral-700 dark:text-neutral-200 group-hover:text-neutral-900 dark:group-hover:text-white'}`}>
                            {company.name}
                        </h3>
                        <div className="flex items-center mt-1 space-x-2">
                            {company.website !== 'N/A' && (
                                <>
                                <Globe className="w-3 h-3 text-neutral-400 group-hover:text-accent transition-colors" />
                                <a 
                                    href={company.website.startsWith('http') ? company.website : `https://${company.website}`} 
                                    target="_blank" 
                                    rel="noreferrer"
                                    onClick={(e) => e.stopPropagation()} 
                                    className="text-xs text-neutral-500 hover:text-accent hover:underline truncate max-w-[150px] transition-colors"
                                >
                                    {company.website.replace(/^https?:\/\/(www\.)?/, '')}
                                </a>
                                </>
                            )}
                        </div>
                        {openRolesCount > 0 && (
                            <div className="mt-2 inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full bg-blue-500/10 text-blue-500 text-[10px] font-bold uppercase">
                                <UserSearch className="w-3 h-3" />
                                {openRolesCount} Open Role{openRolesCount !== 1 && 's'}
                            </div>
                        )}
                        </div>

                        {/* Hot Score Badge */}
                        <div className={`
                            flex items-center gap-1 px-2 py-1 rounded-md text-[10px] font-bold text-white shadow-sm
                            bg-gradient-to-r ${hotColor}
                        `}>
                            <Flame className="w-3 h-3 fill-white/90" />
                            <span>{company.hotScore}%</span>
                        </div>
                    </div>

                    {/* Active Indicator Slide-in */}
                    <div className={`
                        mt-3 flex items-center text-xs font-medium text-accent overflow-hidden transition-all duration-300 ease-out
                        ${isSelected ? 'max-h-6 opacity-100 translate-y-0' : 'max-h-0 opacity-0 -translate-y-2'}
                    `}>
                        <span>Selected</span>
                        <ChevronRight className="w-3 h-3 ml-1" />
                    </div>
                    </div>
                );
                })}

                {/* Infinite Scroll Trigger Area */}
                {companies.length > 0 && (mode === 'discovery' || mode === 'jobs') && (
                <div ref={loadMoreRef} className="py-4 flex flex-col items-center justify-center opacity-70">
                    {isSearching ? (
                        <div className="flex items-center gap-2 text-xs text-neutral-500">
                            <Loader2 className="w-4 h-4 animate-spin text-accent" />
                            <span className="animate-pulse">Loading more results...</span>
                        </div>
                    ) : (
                        <div className="h-4"></div> // Spacer trigger
                    )}
                </div>
                )}
            </>
        )}

        {/* Verified Sources Footer */}
        {sources.length > 0 && (
          <div className="mt-6 pt-4 border-t border-neutral-200 dark:border-white/10 opacity-70 hover:opacity-100 transition-opacity">
            <h4 className="text-[10px] font-bold uppercase text-neutral-500 mb-2">Verified Sources</h4>
            <div className="flex flex-wrap gap-2">
              {sources.map((source, idx) => (
                <a 
                  key={idx}
                  href={source.uri}
                  target="_blank"
                  rel="noreferrer"
                  className="flex items-center gap-1 px-2 py-1 rounded bg-neutral-100 dark:bg-white/5 border border-neutral-200 dark:border-white/10 text-[10px] text-neutral-600 dark:text-neutral-400 hover:text-accent hover:border-accent/30 transition-colors truncate max-w-full"
                  title={source.title}
                >
                  <ExternalLink className="w-3 h-3" />
                  <span className="truncate max-w-[150px]">{source.title || new URL(source.uri).hostname}</span>
                </a>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Archive, Download, Trash2, Crosshair, CheckSquare, Square, Briefcase } from 'lucide-react';
import { Company, SavedJob } from '../types';

interface SidebarProps {
  savedCompanies: Company[];
  savedJobs: SavedJob[];
  onSelectCompany: (company: Company) => void;
  selectedCompanyId: string | null;
  onRemoveCompanies: (ids: string[]) => void;
  onUpdateJobStatus: (id: string, status: 'Saved' | 'Applied' | 'Interviewing' | 'Offer') => void;
  onRemoveJobs: (ids: string[]) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  savedCompanies, 
  savedJobs,
  onSelectCompany, 
  selectedCompanyId,
  onRemoveCompanies,
  onUpdateJobStatus,
  onRemoveJobs
}) => {
  const [view, setView] = useState<'companies' | 'jobs'>('companies');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isSelectionMode, setIsSelectionMode] = useState(false);

  const toggleSelection = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (selectedIds.includes(id)) {
      setSelectedIds(prev => prev.filter(sid => sid !== id));
    } else {
      setSelectedIds(prev => [...prev, id]);
    }
  };

  const toggleSelectionMode = () => {
    if (isSelectionMode) {
      setIsSelectionMode(false);
      setSelectedIds([]);
    } else {
      setIsSelectionMode(true);
    }
  };

  const handleBulkDelete = () => {
    if (view === 'companies') {
        if (window.confirm(`Delete ${selectedIds.length} leads?`)) {
            onRemoveCompanies(selectedIds);
            setSelectedIds([]);
            setIsSelectionMode(false);
        }
    } else {
        if (window.confirm(`Delete ${selectedIds.length} jobs?`)) {
            onRemoveJobs(selectedIds);
            setSelectedIds([]);
            setIsSelectionMode(false);
        }
    }
  };

  const handleExportCSV = () => {
    if (view === 'companies') {
        const targets = isSelectionMode && selectedIds.length > 0
        ? savedCompanies.filter(c => selectedIds.includes(c.id))
        : savedCompanies;

        if (targets.length === 0) return;

        const headers = ['Name', 'Industry', 'Location', 'Website', 'Email', 'Phone', 'Recent Work', 'Hot Score', 'Status'];
        const clean = (text: string) => `"${(text || '').toString().replace(/"/g, '""')}"`;

        const csvContent = [
        headers.join(','),
        ...targets.map(c => [
            clean(c.name),
            clean(c.industry),
            clean(c.location),
            clean(c.website),
            clean(c.email),
            clean(c.phone),
            clean(c.recentWork),
            clean(c.hotScore.toString()),
            clean(c.status)
        ].join(','))
        ].join('\n');

        downloadCSV(csvContent, 'recon_leads');
    } else {
         const targets = isSelectionMode && selectedIds.length > 0
        ? savedJobs.filter(j => selectedIds.includes(j.id))
        : savedJobs;

        if (targets.length === 0) return;

        const headers = ['Title', 'Company', 'Location', 'Type', 'Salary', 'Status', 'Link'];
        const clean = (text: string) => `"${(text || '').toString().replace(/"/g, '""')}"`;

        const csvContent = [
        headers.join(','),
        ...targets.map(j => [
            clean(j.title),
            clean(j.companyName),
            clean(j.location),
            clean(j.type),
            clean(j.salary || ''),
            clean(j.status || 'Saved'),
            clean(j.link || '')
        ].join(','))
        ].join('\n');

        downloadCSV(csvContent, 'recon_jobs');
    }
  };

  const downloadCSV = (content: string, prefix: string) => {
    const blob = new Blob([content], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `${prefix}_${new Date().toISOString().slice(0,10)}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleJobClick = (job: SavedJob) => {
      // Find associated company and select it
      const company = savedCompanies.find(c => c.id === job.companyId);
      if (company) {
          onSelectCompany(company);
      }
  };

  return (
    <div className="h-full flex flex-col bg-neutral-50 dark:bg-neutral-900 border-r border-neutral-200 dark:border-white/5">
      {/* View Toggle Header */}
      <div className="p-4 border-b border-neutral-200 dark:border-white/5 bg-neutral-100/50 dark:bg-white/5">
          <div className="flex bg-white dark:bg-neutral-800 rounded-lg p-1 border border-neutral-200 dark:border-white/5 mb-3" role="tablist">
              <button 
                onClick={() => setView('companies')}
                role="tab"
                aria-selected={view === 'companies'}
                className={`flex-1 flex items-center justify-center gap-2 py-1.5 rounded-md text-[10px] font-bold uppercase transition-all ${view === 'companies' ? 'bg-neutral-100 dark:bg-neutral-700 text-neutral-900 dark:text-white shadow-sm' : 'text-neutral-500'}`}
              >
                  <Archive className="w-3 h-3" /> Leads
              </button>
              <button 
                onClick={() => setView('jobs')}
                role="tab"
                aria-selected={view === 'jobs'}
                className={`flex-1 flex items-center justify-center gap-2 py-1.5 rounded-md text-[10px] font-bold uppercase transition-all ${view === 'jobs' ? 'bg-neutral-100 dark:bg-neutral-700 text-neutral-900 dark:text-white shadow-sm' : 'text-neutral-500'}`}
              >
                  <Briefcase className="w-3 h-3" /> Pipeline
              </button>
          </div>

          <div className="flex justify-between items-center">
            <p className="text-[10px] text-neutral-500 font-medium tracking-wide uppercase">
                {view === 'companies' ? `${savedCompanies.length} Companies` : `${savedJobs.length} Jobs`}
            </p>

            {(view === 'companies' ? savedCompanies.length : savedJobs.length) > 0 && (
                <button 
                    onClick={toggleSelectionMode}
                    className={`p-1.5 rounded transition-colors ${isSelectionMode ? 'text-accent bg-accent/10' : 'text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                    title="Toggle Selection Mode"
                    aria-label="Toggle Selection Mode"
                >
                    <CheckSquare className="w-4 h-4" />
                </button>
            )}
          </div>
      </div>

      <div className="flex-1 overflow-y-auto p-2 space-y-2">
        {/* COMPANIES VIEW */}
        {view === 'companies' && (
             savedCompanies.length === 0 ? (
                <div className="h-48 flex flex-col items-center justify-center text-neutral-400 opacity-60">
                    <Crosshair className="w-8 h-8 mb-2 stroke-1" />
                    <span className="text-xs">No saved leads</span>
                </div>
             ) : (
                savedCompanies.map((company) => {
                    const isChecked = selectedIds.includes(company.id);
                    return (
                    <div
                        key={company.id}
                        onClick={() => isSelectionMode ? toggleSelection(company.id, { stopPropagation: () => {} } as any) : onSelectCompany(company)}
                        role="button"
                        aria-pressed={selectedCompanyId === company.id}
                        className={`
                        group relative p-3 rounded-lg cursor-pointer border transition-all duration-200 flex items-center gap-3
                        ${selectedCompanyId === company.id 
                            ? 'bg-white dark:bg-neutral-800 border-accent shadow-sm' 
                            : 'bg-transparent border-transparent hover:bg-neutral-100 dark:hover:bg-neutral-800 hover:border-neutral-200 dark:hover:border-white/10'}
                        `}
                    >
                        {isSelectionMode && (
                        <div 
                            onClick={(e) => toggleSelection(company.id, e)}
                            role="checkbox"
                            aria-checked={isChecked}
                            className={`shrink-0 text-neutral-400 ${isChecked ? 'text-accent' : 'hover:text-neutral-500'}`}
                        >
                            {isChecked ? <CheckSquare className="w-4 h-4" /> : <Square className="w-4 h-4" />}
                        </div>
                        )}

                        <div className="flex-1 min-w-0">
                        <h4 className={`text-xs font-bold truncate ${selectedCompanyId === company.id ? 'text-neutral-900 dark:text-white' : 'text-neutral-600 dark:text-neutral-400'}`}>
                            {company.name}
                        </h4>
                        <div className="flex items-center gap-2 mt-0.5">
                            <span className="text-[10px] text-neutral-400 truncate max-w-[80px]">{company.industry}</span>
                            <div className={`w-1.5 h-1.5 rounded-full ${company.status === 'Contacted' ? 'bg-green-500' : 'bg-amber-500'}`}></div>
                        </div>
                        </div>

                        {!isSelectionMode && (
                        <button
                            onClick={(e) => { e.stopPropagation(); onRemoveCompanies([company.id]); }}
                            className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-500 text-neutral-400 transition-opacity"
                            title="Remove Lead"
                            aria-label="Remove Lead"
                        >
                            <Trash2 className="w-3 h-3" />
                        </button>
                        )}
                    </div>
                    );
                })
             )
        )}

        {/* JOBS VIEW */}
        {view === 'jobs' && (
             savedJobs.length === 0 ? (
                <div className="h-48 flex flex-col items-center justify-center text-neutral-400 opacity-60">
                    <Briefcase className="w-8 h-8 mb-2 stroke-1" />
                    <span className="text-xs">No tracked jobs</span>
                </div>
             ) : (
                 savedJobs.map((job) => {
                     const isChecked = selectedIds.includes(job.id);
                     const statusColors = {
                         'Saved': 'bg-neutral-500',
                         'Applied': 'bg-blue-500',
                         'Interviewing': 'bg-purple-500',
                         'Offer': 'bg-green-500'
                     };

                     return (
                         <div
                            key={job.id}
                            className="group relative p-3 rounded-lg border border-neutral-200 dark:border-white/5 bg-white dark:bg-neutral-800/50 hover:bg-neutral-50 dark:hover:bg-neutral-800 transition-all"
                         >
                             <div className="flex items-start gap-3">
                                {isSelectionMode && (
                                    <div 
                                        onClick={(e) => toggleSelection(job.id, e)}
                                        role="checkbox"
                                        aria-checked={isChecked}
                                        className={`mt-1 shrink-0 text-neutral-400 cursor-pointer ${isChecked ? 'text-accent' : 'hover:text-neutral-500'}`}
                                    >
                                        {isChecked ? <CheckSquare className="w-4 h-4" /> : <Square className="w-4 h-4" />}
                                    </div>
                                )}
                                <div className="flex-1 min-w-0 cursor-pointer" onClick={() => handleJobClick(job)}>
                                    <h4 className="text-xs font-bold text-neutral-900 dark:text-white truncate">{job.title}</h4>
                                    <p className="text-[10px] text-neutral-500 truncate">{job.companyName}</p>
                                    <div className="mt-2 flex items-center justify-between">
                                        <select 
                                            value={job.status || 'Saved'}
                                            onChange={(e) => onUpdateJobStatus(job.id, e.target.value as any)}
                                            onClick={(e) => e.stopPropagation()}
                                            aria-label="Update Job Status"
                                            className={`text-[9px] font-bold uppercase rounded px-1.5 py-0.5 border-none outline-none cursor-pointer text-white ${statusColors[job.status || 'Saved'] || 'bg-neutral-500'}`}
                                        >
                                            <option value="Saved" className="text-black">Saved</option>
                                            <option value="Applied" className="text-black">Applied</option>
                                            <option value="Interviewing" className="text-black">Interviewing</option>
                                            <option value="Offer" className="text-black">Offer</option>
                                        </select>
                                    </div>
                                </div>
                                {!isSelectionMode && (
                                    <button
                                        onClick={(e) => { e.stopPropagation(); onRemoveJobs([job.id]); }}
                                        className="opacity-0 group-hover:opacity-100 p-1 hover:text-red-500 text-neutral-400 transition-opacity"
                                        title="Remove Job"
                                        aria-label="Remove Job"
                                    >
                                        <Trash2 className="w-3 h-3" />
                                    </button>
                                )}
                             </div>
                         </div>
                     );
                 })
             )
        )}
      </div>

      {/* Actions Toolbar */}
      {(view === 'companies' ? savedCompanies.length : savedJobs.length) > 0 && (
         <div className="p-3 border-t border-neutral-200 dark:border-white/5 bg-neutral-100/50 dark:bg-black/20 space-y-2">
            {isSelectionMode ? (
               <div className="flex gap-2 animate-fade-in-up">
                  <button
                    onClick={handleBulkDelete}
                    disabled={selectedIds.length === 0}
                    className="flex-1 py-2 rounded-lg bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 text-xs font-bold uppercase disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 transition-colors"
                  >
                    <Trash2 className="w-3 h-3" />
                    <span>Delete ({selectedIds.length})</span>
                  </button>
                  <button
                    onClick={handleExportCSV}
                    disabled={selectedIds.length === 0}
                    className="flex-1 py-2 rounded-lg bg-accent/10 hover:bg-accent/20 text-accent text-xs font-bold uppercase disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 transition-colors"
                  >
                    <Download className="w-3 h-3" />
                    <span>Export ({selectedIds.length})</span>
                  </button>
               </div>
            ) : (
                <button
                    onClick={handleExportCSV}
                    className="w-full py-2 rounded-lg bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-white/10 hover:border-accent hover:text-accent text-neutral-500 dark:text-neutral-400 text-xs font-bold uppercase flex items-center justify-center gap-2 transition-all shadow-sm"
                >
                    <Download className="w-3 h-3" />
                    <span>Export All CSV</span>
                </button>
            )}
         </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Target, Send, Loader2, Sparkles, Copy, Check, Bot, Phone, Mail, Award, Globe, Linkedin, Twitter, Facebook, Instagram, Youtube, Link as LinkIcon, Zap, TrendingUp, DollarSign, Newspaper, Edit3, Bookmark, ShieldCheck, MapPin, Briefcase, UserPlus, Search, FileText, UserSearch, Briefcase as BriefcaseIcon, PlusCircle, CheckCircle, ExternalLink } from 'lucide-react';
import { Company, Pitch, Job, SavedJob } from '../types';
import { generatePitch } from '../services/geminiService';

interface IntelligencePaneProps {
  company: Company | null;
  onToggleSave: () => void;
  isSaved: boolean;
  onTrackJob: (job: Job) => void;
  savedJobs: SavedJob[];
}

type Tab = 'overview' | 'insights' | 'jobs' | 'outreach';
type PitchFormat = 'email' | 'linkedin_connect' | 'linkedin_inmail';

export const IntelligencePane: React.FC<IntelligencePaneProps> = ({ 
    company, 
    onToggleSave, 
    isSaved,
    onTrackJob,
    savedJobs 
}) => {
  const [activeTab, setActiveTab] = useState<Tab>('overview');
  const [skills, setSkills] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generatedPitches, setGeneratedPitches] = useState<Pitch[]>([]);
  const [activePitchIndex, setActivePitchIndex] = useState(0);
  const [copied, setCopied] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [pitchFormat, setPitchFormat] = useState<PitchFormat>('email');

  // Outreach Context State
  const [outreachContext, setOutreachContext] = useState<'sales' | 'job_application'>('sales');
  const [targetJobTitle, setTargetJobTitle] = useState('');

  React.useEffect(() => {
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
    setActiveTab('overview');
    // Default to 'jobs' tab if company has open roles and we are in that mindset? No, Overview is safer.
  }, [company?.id]);

  const handleFormatChange = (format: PitchFormat) => {
    setPitchFormat(format);
    setGeneratedPitches([]);
    setActivePitchIndex(0);
    setIsEditing(false);
  };

  const handleGenerate = async () => {
    if (!company || !skills) return;

    setIsGenerating(true);
    setGeneratedPitches([]);
    setActivePitchIndex(0);

    try {
      const signalContext = company.signals.map(s => `${s.type}: ${s.text}`);

      const results = await generatePitch({
        companyName: company.name,
        industry: company.industry,
        userSkills: skills,
        tone: 'Professional',
        companySignals: signalContext,
        format: pitchFormat,
        context: outreachContext,
        jobTitle: targetJobTitle
      });
      setGeneratedPitches(results);
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const getSignalIcon = (type: string) => {
    const t = type.toLowerCase();
    if (t.includes('fund') || t.includes('money')) return <DollarSign className="w-3 h-3 text-emerald-500" />;
    if (t.includes('hir') || t.includes('team') || t.includes('growth')) return <TrendingUp className="w-3 h-3 text-blue-500" />;
    if (t.includes('news') || t.includes('press')) return <Newspaper className="w-3 h-3 text-purple-500" />;
    if (t.includes('loc') || t.includes('hq')) return <MapPin className="w-3 h-3 text-orange-500" />;
    return <ShieldCheck className="w-3 h-3 text-accent" />;
  };

  const getSocialLinks = () => {
    if (!company || !company.socials || company.socials === 'N/A' || company.socials === 'None') return [];

    return company.socials
      .split(/[\s,\n]+/)
      .map(s => s.trim())
      .filter(s => s.length > 0 && !s.toLowerCase().includes('n/a'))
      .map((rawLink, index) => {
        let url = rawLink.replace(/[\[\]()]/g, '');
        if (!url.startsWith('http')) url = `https://${url}`;
        if (!url.includes('.') || url.length < 8) return null;

        let icon = <LinkIcon className="w-4 h-4" />;
        const lowerUrl = url.toLowerCase();

        if (lowerUrl.includes('linkedin')) icon = <Linkedin className="w-4 h-4" />;
        else if (lowerUrl.includes('twitter') || lowerUrl.includes('x.com')) icon = <Twitter className="w-4 h-4" />;
        else if (lowerUrl.includes('facebook')) icon = <Facebook className="w-4 h-4" />;
        else if (lowerUrl.includes('instagram')) icon = <Instagram className="w-4 h-4" />;
        else if (lowerUrl.includes('youtube')) icon = <Youtube className="w-4 h-4" />;

        return { url, icon, key: index };
      })
      .filter((link): link is { url: string; icon: React.ReactElement; key: number } => link !== null);
  };

  if (!company) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-neutral-400 select-none bg-neutral-50/50 dark:bg-black/20">
         <div className="max-w-md p-8">
            <div className="flex items-center gap-3 mb-6">
                <div className="p-3 bg-accent/10 rounded-xl">
