import { useState, useEffect, useRef } from 'react';
import { supabase } from '../services/supabase';
import { safeStorage } from '../utils/storage';
import { Company, SavedJob } from '../types';

// Generates a persistent device ID to identify the user without login
const getDeviceId = () => {
    let id = safeStorage.get<string>('recon_device_id', '');
    if (!id) {
        id = crypto.randomUUID();
        safeStorage.set('recon_device_id', id);
    }
    return id;
};

export const useDataSync = () => {
    // Initialize with Local Storage for instant load (Offline First)
    const [savedCompanies, setSavedCompanies] = useState<Company[]>(() => 
        safeStorage.get<Company[]>('recon_saved_targets', [])
    );
    const [savedJobs, setSavedJobs] = useState<SavedJob[]>(() => 
        safeStorage.get<SavedJob[]>('recon_saved_jobs', [])
    );

    const [isSyncing, setIsSyncing] = useState(false);
    const [hasRemoteConnection, setHasRemoteConnection] = useState(!!supabase);
    const deviceId = useRef(getDeviceId()).current;

    // 1. On Mount: Fetch latest data from Cloud and merge
    useEffect(() => {
        if (!supabase) return;

        const syncRemote = async () => {
            setIsSyncing(true);
            try {
                // Fetch remote state
                const { data, error } = await supabase
                    .from('user_data')
                    .select('data')
                    .eq('user_id', deviceId)
                    .single();

                if (data && data.data) {
                    const { companies, jobs } = data.data;

                    // Simple Strategy: Remote data overwrites local on startup
                    // This ensures multiple devices stay consistent
                    if (companies) {
                        setSavedCompanies(companies);
                        safeStorage.set('recon_saved_targets', companies);
                    }
                    if (jobs) {
                        setSavedJobs(jobs);
                        safeStorage.set('recon_saved_jobs', jobs);
                    }
                } else if (!data) {
                    // If no remote data exists yet, push our local data up
                    await saveToRemote(savedCompanies, savedJobs);
                }
            } catch (e) {
                console.warn("Sync: Failed to fetch remote data", e);
            } finally {
                setIsSyncing(false);
            }
        };

        syncRemote();
    }, []);

    // Helper to push state to Supabase
    const saveToRemote = async (companies: Company[], jobs: SavedJob[]) => {
        if (!supabase) return;
        try {
            await supabase.from('user_data').upsert({
                user_id: deviceId,
                data: { companies, jobs },
                updated_at: new Date().toISOString()
            });
        } catch (e) {
            console.error("Sync: Save failed", e);
        }
    };

    // Public API: Update Companies (Optimistic + Async Sync)
    const updateCompanies = (newCompanies: Company[]) => {
        setSavedCompanies(newCompanies);
        safeStorage.set('recon_saved_targets', newCompanies); // Local Persist
        saveToRemote(newCompanies, savedJobs); // Remote Persist
    };

    // Public API: Update Jobs (Optimistic + Async Sync)
    const updateJobs = (newJobs: SavedJob[]) => {
        setSavedJobs(newJobs);
        safeStorage.set('recon_saved_jobs', newJobs); // Local Persist
        saveToRemote(savedCompanies, newJobs); // Remote Persist
    };

    return {
        savedCompanies,
        savedJobs,
        updateCompanies,
        updateJobs,
        isSyncing,
        isOnline: hasRemoteConnection
    };
};

